//! Strong references go parent -> first child and node -> next sibling;
//! everything else (parent, previous sibling, last child) is weak.  The
//! reference-counting layout is observable through the lazy traversal used by
//! the `--remove-nodes` handling, so it is kept simple and explicit.

use std::cell::{Ref, RefCell, RefMut};
use std::collections::BTreeMap;
use std::rc::{Rc, Weak};

pub const NS_HTML: &str = "http://www.w3.org/1999/xhtml";
pub const NS_MATHML: &str = "http://www.w3.org/1998/Math/MathML";
pub const NS_SVG: &str = "http://www.w3.org/2000/svg";
pub const NS_XLINK: &str = "http://www.w3.org/1999/xlink";
pub const NS_XML: &str = "http://www.w3.org/XML/1998/namespace";
pub const NS_XMLNS: &str = "http://www.w3.org/2000/xmlns/";

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct QualName {
    pub ns: String,
    pub local: String,
}

impl QualName {
    pub fn new(ns: &str, local: &str) -> QualName {
        QualName { ns: ns.to_string(), local: local.to_string() }
    }
    pub fn html(local: &str) -> QualName {
        QualName::new(NS_HTML, local)
    }
    pub fn is_html(&self, local: &str) -> bool {
        self.ns == NS_HTML && self.local == local
    }
}

/// Attribute key: (namespace, local name).  Ordering is namespace first, then
/// local name, which is the order attributes are serialised in.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct AttrName {
    pub ns: String,
    pub local: String,
}

#[derive(Clone, Debug)]
pub struct Attribute {
    /// Prefix as it appeared in the source (e.g. `xlink`), if any.
    pub prefix: Option<String>,
    pub value: String,
}

#[derive(Clone, Debug, Default)]
pub struct Attributes {
    pub map: BTreeMap<AttrName, Attribute>,
}

impl Attributes {
    pub fn get(&self, local: &str) -> Option<&str> {
        self.map
            .get(&AttrName { ns: String::new(), local: local.to_string() })
            .map(|a| a.value.as_str())
    }
    pub fn contains(&self, local: &str) -> bool {
        self.map.contains_key(&AttrName { ns: String::new(), local: local.to_string() })
    }
    pub fn insert(&mut self, local: &str, value: String) {
        self.map.insert(
            AttrName { ns: String::new(), local: local.to_string() },
            Attribute { prefix: None, value },
        );
    }
}

#[derive(Debug)]
pub struct ElementData {
    pub name: QualName,
    pub attributes: RefCell<Attributes>,
    pub template_contents: Option<NodeRef>,
}

#[derive(Debug)]
pub struct Doctype {
    pub name: String,
    pub public_id: String,
    pub system_id: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QuirksMode {
    Quirks,
    LimitedQuirks,
    NoQuirks,
}

#[derive(Debug)]
pub struct DocumentData {
    pub quirks_mode: RefCell<QuirksMode>,
}

#[derive(Debug)]
pub enum NodeData {
    Element(ElementData),
    Text(RefCell<String>),
    Comment(RefCell<String>),
    ProcessingInstruction(RefCell<(String, String)>),
    Doctype(Doctype),
    Document(DocumentData),
    DocumentFragment,
}

pub struct Node {
    parent: RefCell<Option<Weak<Node>>>,
    previous_sibling: RefCell<Option<Weak<Node>>>,
    next_sibling: RefCell<Option<Rc<Node>>>,
    first_child: RefCell<Option<Rc<Node>>>,
    last_child: RefCell<Option<Weak<Node>>>,
    pub data: NodeData,
}

impl std::fmt::Debug for Node {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Node({:?})", self.data)
    }
}

/// Avoid deep recursion when dropping long sibling chains / deep trees.
impl Drop for Node {
    fn drop(&mut self) {
        let mut stack: Vec<Rc<Node>> = Vec::new();
        if let Some(rc) = take_if_unique_strong(&self.first_child) {
            stack.push(rc);
        }
        if let Some(rc) = take_if_unique_strong(&self.next_sibling) {
            stack.push(rc);
        }
        while let Some(rc) = stack.pop() {
            if let Some(n) = take_if_unique_strong(&rc.first_child) {
                stack.push(n);
            }
            if let Some(n) = take_if_unique_strong(&rc.next_sibling) {
                stack.push(n);
            }
            // `rc` is dropped here with no uniquely-owned children or siblings left.
        }
    }
}

fn take_if_unique_strong(cell: &RefCell<Option<Rc<Node>>>) -> Option<Rc<Node>> {
    let mut b = cell.borrow_mut();
    match &*b {
        Some(rc) if Rc::strong_count(rc) == 1 => b.take(),
        _ => None,
    }
}

#[derive(Clone, Debug)]
pub struct NodeRef(pub Rc<Node>);

impl PartialEq for NodeRef {
    fn eq(&self, other: &NodeRef) -> bool {
        Rc::ptr_eq(&self.0, &other.0)
    }
}
impl Eq for NodeRef {}

impl std::ops::Deref for NodeRef {
    type Target = Node;
    fn deref(&self) -> &Node {
        &self.0
    }
}

impl NodeRef {
    pub fn new(data: NodeData) -> NodeRef {
        NodeRef(Rc::new(Node {
            parent: RefCell::new(None),
            previous_sibling: RefCell::new(None),
            next_sibling: RefCell::new(None),
            first_child: RefCell::new(None),
            last_child: RefCell::new(None),
            data,
        }))
    }

    pub fn new_element(name: QualName, attributes: Attributes, template_contents: Option<NodeRef>) -> NodeRef {
        NodeRef::new(NodeData::Element(ElementData {
            name,
            attributes: RefCell::new(attributes),
            template_contents,
        }))
    }

    pub fn new_text(text: String) -> NodeRef {
        NodeRef::new(NodeData::Text(RefCell::new(text)))
    }

    pub fn new_comment(text: String) -> NodeRef {
        NodeRef::new(NodeData::Comment(RefCell::new(text)))
    }

    pub fn new_doctype(name: String, public_id: String, system_id: String) -> NodeRef {
        NodeRef::new(NodeData::Doctype(Doctype { name, public_id, system_id }))
    }

    pub fn new_document() -> NodeRef {
        NodeRef::new(NodeData::Document(DocumentData {
            quirks_mode: RefCell::new(QuirksMode::NoQuirks),
        }))
    }

    pub fn new_fragment() -> NodeRef {
        NodeRef::new(NodeData::DocumentFragment)
    }

    pub fn as_element(&self) -> Option<&ElementData> {
        match self.data {
            NodeData::Element(ref e) => Some(e),
            _ => None,
        }
    }

    pub fn as_text(&self) -> Option<&RefCell<String>> {
        match self.data {
            NodeData::Text(ref t) => Some(t),
            _ => None,
        }
    }

    pub fn as_document(&self) -> Option<&DocumentData> {
        match self.data {
            NodeData::Document(ref d) => Some(d),
            _ => None,
        }
    }

    pub fn is_element(&self) -> bool {
        matches!(self.data, NodeData::Element(_))
    }

    pub fn parent(&self) -> Option<NodeRef> {
        self.parent.borrow().as_ref().and_then(|w| w.upgrade()).map(NodeRef)
    }

    pub fn first_child(&self) -> Option<NodeRef> {
        self.first_child.borrow().as_ref().map(|rc| NodeRef(rc.clone()))
    }

    pub fn last_child(&self) -> Option<NodeRef> {
        self.last_child.borrow().as_ref().and_then(|w| w.upgrade()).map(NodeRef)
    }

    pub fn previous_sibling(&self) -> Option<NodeRef> {
        self.previous_sibling.borrow().as_ref().and_then(|w| w.upgrade()).map(NodeRef)
    }

    pub fn next_sibling(&self) -> Option<NodeRef> {
        self.next_sibling.borrow().as_ref().map(|rc| NodeRef(rc.clone()))
    }

    pub fn children(&self) -> Children {
        Children { next: self.first_child() }
    }

    /// Detach this node from its parent and siblings.
    pub fn detach(&self) {
        let parent_weak = self.parent.borrow_mut().take();
        let previous_sibling_weak = self.previous_sibling.borrow_mut().take();
        let next_sibling_strong = self.next_sibling.borrow_mut().take();

        let previous_sibling_opt = previous_sibling_weak.as_ref().and_then(|w| w.upgrade());

        if let Some(next) = next_sibling_strong.as_ref() {
            *next.previous_sibling.borrow_mut() = previous_sibling_weak;
        } else if let Some(parent_weak) = parent_weak.as_ref() {
            if let Some(parent) = parent_weak.upgrade() {
                *parent.last_child.borrow_mut() = previous_sibling_weak;
            }
        }

        if let Some(prev) = previous_sibling_opt {
            *prev.next_sibling.borrow_mut() = next_sibling_strong;
        } else if let Some(parent_weak) = parent_weak.as_ref() {
            if let Some(parent) = parent_weak.upgrade() {
                *parent.first_child.borrow_mut() = next_sibling_strong;
            }
        }
    }

    pub fn append(&self, new_child: NodeRef) {
        new_child.detach();
        *new_child.parent.borrow_mut() = Some(Rc::downgrade(&self.0));
        if let Some(last_child_weak) = self.last_child.borrow_mut().take() {
            if let Some(last_child) = last_child_weak.upgrade() {
                *new_child.previous_sibling.borrow_mut() = Some(last_child_weak);
                debug_assert!(last_child.next_sibling.borrow().is_none());
                *last_child.next_sibling.borrow_mut() = Some(new_child.0.clone());
                *self.last_child.borrow_mut() = Some(Rc::downgrade(&new_child.0));
                return;
            }
        }
        debug_assert!(self.first_child.borrow().is_none());
        *self.first_child.borrow_mut() = Some(new_child.0.clone());
        *self.last_child.borrow_mut() = Some(Rc::downgrade(&new_child.0));
    }

    pub fn prepend(&self, new_child: NodeRef) {
        new_child.detach();
        *new_child.parent.borrow_mut() = Some(Rc::downgrade(&self.0));
        if let Some(first_child) = self.first_child.borrow_mut().take() {
            *first_child.previous_sibling.borrow_mut() = Some(Rc::downgrade(&new_child.0));
            *new_child.next_sibling.borrow_mut() = Some(first_child);
        } else {
            *self.last_child.borrow_mut() = Some(Rc::downgrade(&new_child.0));
        }
        *self.first_child.borrow_mut() = Some(new_child.0.clone());
    }

    /// Insert `new_sibling` immediately after `self`.
    pub fn insert_after(&self, new_sibling: NodeRef) {
        new_sibling.detach();
        *new_sibling.parent.borrow_mut() = self.parent.borrow().clone();
        *new_sibling.previous_sibling.borrow_mut() = Some(Rc::downgrade(&self.0));
        if let Some(next_sibling) = self.next_sibling.borrow_mut().take() {
            *next_sibling.previous_sibling.borrow_mut() = Some(Rc::downgrade(&new_sibling.0));
            *new_sibling.next_sibling.borrow_mut() = Some(next_sibling);
        } else if let Some(parent) = self.parent() {
            *parent.last_child.borrow_mut() = Some(Rc::downgrade(&new_sibling.0));
        }
        *self.next_sibling.borrow_mut() = Some(new_sibling.0.clone());
    }

    /// Insert `new_sibling` immediately before `self`.
    pub fn insert_before(&self, new_sibling: NodeRef) {
        new_sibling.detach();
        *new_sibling.parent.borrow_mut() = self.parent.borrow().clone();
        *new_sibling.next_sibling.borrow_mut() = Some(self.0.clone());
        if let Some(previous_sibling_weak) = self.previous_sibling.borrow_mut().take() {
            if let Some(previous_sibling) = previous_sibling_weak.upgrade() {
                *new_sibling.previous_sibling.borrow_mut() = Some(previous_sibling_weak);
                let old_next = previous_sibling.next_sibling.borrow_mut().take();
                debug_assert!(old_next.map_or(false, |n| Rc::ptr_eq(&n, &self.0)));
                *previous_sibling.next_sibling.borrow_mut() = Some(new_sibling.0.clone());
                *self.previous_sibling.borrow_mut() = Some(Rc::downgrade(&new_sibling.0));
                return;
            }
        }
        if let Some(parent) = self.parent() {
            // Replace the parent's strong reference to self with new_sibling.
            let _old = parent.first_child.borrow_mut().take();
            *parent.first_child.borrow_mut() = Some(new_sibling.0.clone());
        }
        *self.previous_sibling.borrow_mut() = Some(Rc::downgrade(&new_sibling.0));
    }

    /// Concatenation of all descendant text nodes.
    pub fn text_contents(&self) -> String {
        let mut s = String::new();
        for node in self.inclusive_descendants() {
            if let NodeData::Text(ref t) = node.data {
                s.push_str(&t.borrow());
            }
        }
        s
    }

    pub fn traverse_inclusive(&self) -> Traverse {
        Traverse {
            root: self.clone(),
            next: Some(NodeEdge::Start(self.clone())),
        }
    }

    pub fn inclusive_descendants(&self) -> Descendants {
        Descendants(self.traverse_inclusive())
    }

    pub fn descendants(&self) -> Descendants {
        let mut d = self.inclusive_descendants();
        // Skip self.
        let _ = d.next();
        d
    }

    pub fn borrow_text(&self) -> Option<Ref<'_, String>> {
        self.as_text().map(|t| t.borrow())
    }

    pub fn borrow_text_mut(&self) -> Option<RefMut<'_, String>> {
        self.as_text().map(|t| t.borrow_mut())
    }
}

pub struct Children {
    next: Option<NodeRef>,
}

impl Iterator for Children {
    type Item = NodeRef;
    fn next(&mut self) -> Option<NodeRef> {
        let n = self.next.take()?;
        self.next = n.next_sibling();
        Some(n)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NodeEdge {
    Start(NodeRef),
    End(NodeRef),
}

/// Pre-order traversal yielding start/end edges.  The next edge is computed
/// eagerly when an item is yielded, which matters when the tree is mutated
/// during iteration: iteration silently stops when a node without a parent
/// (other than the root) is reached.
pub struct Traverse {
    root: NodeRef,
    next: Option<NodeEdge>,
}

impl Iterator for Traverse {
    type Item = NodeEdge;
    fn next(&mut self) -> Option<NodeEdge> {
        let next = self.next.take()?;
        self.next = match next {
            NodeEdge::Start(ref node) => match node.first_child() {
                Some(child) => Some(NodeEdge::Start(child)),
                None => Some(NodeEdge::End(node.clone())),
            },
            NodeEdge::End(ref node) => {
                if *node == self.root {
                    None
                } else {
                    match node.next_sibling() {
                        Some(sibling) => Some(NodeEdge::Start(sibling)),
                        None => node.parent().map(NodeEdge::End),
                    }
                }
            }
        };
        Some(next)
    }
}

pub struct Descendants(pub Traverse);

impl Iterator for Descendants {
    type Item = NodeRef;
    fn next(&mut self) -> Option<NodeRef> {
        loop {
            match self.0.next() {
                Some(NodeEdge::Start(node)) => return Some(node),
                Some(NodeEdge::End(_)) => {}
                None => return None,
            }
        }
    }
}
