//! HTML tokenizer following the WHATWG HTML living standard.

use crate::entities::ENTITIES;
use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(Debug, Clone)]
pub struct Tag {
    pub name: String,
    pub attrs: Vec<(String, String)>,
    pub self_closing: bool,
}

#[derive(Debug, Clone)]
pub enum Token {
    Doctype {
        name: Option<String>,
        public_id: Option<String>,
        system_id: Option<String>,
        force_quirks: bool,
    },
    StartTag(Tag),
    EndTag(Tag),
    Comment(String),
    /// A run of characters.  Runs never mix whitespace and non-whitespace
    /// characters, and a NUL character is always delivered on its own.
    Characters(String),
