}

pub trait TokenSink {
    fn process_token(&mut self, token: Token) -> SinkResult;
    /// Whether the adjusted current node exists and is not in the HTML namespace.
    fn adjusted_current_node_not_html(&self) -> bool;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Data,
