fn is_ws(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\x0C' | ' ')
}

struct DoctypeBuilder {
    name: Option<String>,
    public_id: Option<String>,
    system_id: Option<String>,
    force_quirks: bool,
}

pub struct Tokenizer<'a, S: TokenSink> {
    input: Vec<char>,
    pos: usize,
    state: State,
    return_state: State,
    sink: &'a mut S,
    // Current tag being built.
    tag_name: String,
    tag_is_end: bool,
    tag_attrs: Vec<(String, String)>,
    tag_self_closing: bool,
    cur_attr_name: String,
    cur_attr_value: String,
    cur_attr_dropped: bool,
    last_start_tag_name: Option<String>,
    temp_buf: String,
    comment: String,
    doctype: DoctypeBuilder,
    // Pending character output.
    pending: String,
    pending_ws: Option<bool>,
}

fn entity_map() -> &'static HashMap<&'static str, &'static str> {
    static MAP: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    MAP.get_or_init(|| ENTITIES.iter().cloned().collect())
}

fn max_entity_len() -> usize {
    static LEN: OnceLock<usize> = OnceLock::new();
    *LEN.get_or_init(|| ENTITIES.iter().map(|(k, _)| k.len()).max().unwrap_or(0))
}

impl<'a, S: TokenSink> Tokenizer<'a, S> {
    pub fn new(input: &str, sink: &'a mut S) -> Self {
        // Preprocess: normalise newlines, strip a leading BOM.
        let mut chars: Vec<char> = Vec::with_capacity(input.len());
        let mut iter = input.chars().peekable();
        if iter.peek() == Some(&'\u{FEFF}') {
            iter.next();
        }
        while let Some(c) = iter.next() {
            if c == '\r' {
                if iter.peek() == Some(&'\n') {
                    iter.next();
                }
                chars.push('\n');
            } else {
                chars.push(c);
            }
        }
        Tokenizer {
            input: chars,
            pos: 0,
            state: State::Data,
            return_state: State::Data,
            sink,
            tag_name: String::new(),
            tag_is_end: false,
            tag_attrs: Vec::new(),
            tag_self_closing: false,
            cur_attr_name: String::new(),
            cur_attr_value: String::new(),
            cur_attr_dropped: false,
            last_start_tag_name: None,
            temp_buf: String::new(),
            comment: String::new(),
            doctype: DoctypeBuilder { name: None, public_id: None, system_id: None, force_quirks: false },
            pending: String::new(),
            pending_ws: None,
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.input.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn reconsume(&mut self) {
        self.pos -= 1;
    }

    fn lookahead_ci(&self, s: &str) -> bool {
        let mut i = self.pos;
        for sc in s.chars() {
            match self.input.get(i) {
                Some(&c) if c.to_ascii_lowercase() == sc.to_ascii_lowercase() => i += 1,
                _ => return false,
            }
        }
        true
    }

    fn lookahead(&self, s: &str) -> bool {
        let mut i = self.pos;
        for sc in s.chars() {
            match self.input.get(i) {
                Some(&c) if c == sc => i += 1,
                _ => return false,
            }
        }
        true
    }

    // ---- character output ----

    fn emit_char(&mut self, c: char) {
        let ws = is_ws(c);
        let nul = c == '\0';
        if nul {
            self.flush_chars();
            self.pending.push(c);
            self.flush_chars();
            return;
        }
        match self.pending_ws {
            Some(w) if w == ws => {}
            Some(_) => self.flush_chars(),
            None => {}
        }
        self.pending_ws = Some(ws);
        self.pending.push(c);
    }

    fn emit_str(&mut self, s: &str) {
        for c in s.chars() {
            self.emit_char(c);
        }
    }

    fn flush_chars(&mut self) {
        if !self.pending.is_empty() {
            let s = std::mem::take(&mut self.pending);
            self.pending_ws = None;
            self.process(Token::Characters(s));
        }
        self.pending_ws = None;
    }

    fn process(&mut self, token: Token) {
        match self.sink.process_token(token) {
            SinkResult::Continue => {}
            SinkResult::Raw(kind) => {
                self.state = match kind {
                    RawKind::Rcdata => State::Rcdata,
                    RawKind::Rawtext => State::Rawtext,
                    RawKind::ScriptData => State::ScriptData,
                    RawKind::Plaintext => State::Plaintext,
                };
            }
        }
    }

    fn emit_token(&mut self, token: Token) {
        self.flush_chars();
        self.process(token);
    }

    // ---- tag helpers ----

    fn start_tag(&mut self, is_end: bool) {
        self.tag_name.clear();
        self.tag_is_end = is_end;
        self.tag_attrs.clear();
        self.tag_self_closing = false;
        self.cur_attr_name.clear();
        self.cur_attr_value.clear();
        self.cur_attr_dropped = false;
    }

    fn start_attr(&mut self) {
        self.finish_attr();
        self.cur_attr_name.clear();
        self.cur_attr_value.clear();
        self.cur_attr_dropped = false;
    }

    /// Called when an attribute name is complete: check for duplicates.
    fn check_dup_attr(&mut self) {
        if self.tag_attrs.iter().any(|(n, _)| *n == self.cur_attr_name) {
            self.cur_attr_dropped = true;
        }
    }

    fn finish_attr(&mut self) {
        if !self.cur_attr_name.is_empty() && !self.cur_attr_dropped {
            let name = std::mem::take(&mut self.cur_attr_name);
            let value = std::mem::take(&mut self.cur_attr_value);
            self.tag_attrs.push((name, value));
        }
        self.cur_attr_name.clear();
        self.cur_attr_value.clear();
        self.cur_attr_dropped = false;
    }

    fn emit_tag(&mut self) {
        self.finish_attr();
        let tag = Tag {
            name: std::mem::take(&mut self.tag_name),
            attrs: std::mem::take(&mut self.tag_attrs),
            self_closing: self.tag_self_closing,
        };
        if self.tag_is_end {
            self.emit_token(Token::EndTag(tag));
        } else {
            self.last_start_tag_name = Some(tag.name.clone());
            self.emit_token(Token::StartTag(tag));
        }
    }

    fn is_appropriate_end_tag(&self) -> bool {
        match &self.last_start_tag_name {
            Some(n) => *n == self.tag_name,
            None => false,
        }
    }

    fn emit_comment(&mut self) {
        let c = std::mem::take(&mut self.comment);
        self.emit_token(Token::Comment(c));
    }

    fn emit_doctype(&mut self) {
        let d = Token::Doctype {
            name: self.doctype.name.take(),
            public_id: self.doctype.public_id.take(),
            system_id: self.doctype.system_id.take(),
            force_quirks: self.doctype.force_quirks,
        };
        self.doctype.force_quirks = false;
        self.emit_token(d);
    }

    fn in_attribute(&self) -> bool {
        matches!(
            self.return_state,
            State::AttributeValueDoubleQuoted | State::AttributeValueSingleQuoted | State::AttributeValueUnquoted
        )
    }

    /// Emit (or append to the attribute value) a decoded character reference.
    fn flush_code_points_consumed_as_char_ref(&mut self) {
        let buf = std::mem::take(&mut self.temp_buf);
        if self.in_attribute() {
            self.cur_attr_value.push_str(&buf);
        } else {
            self.emit_str(&buf);
        }
    }

    fn emit_temp_buf_chars(&mut self) {
        let buf = std::mem::take(&mut self.temp_buf);
        self.emit_str(&buf);
    }

    // ---- character reference ----

    fn consume_char_ref(&mut self) {
        // We're positioned right after the '&'.
        self.temp_buf.clear();
        self.temp_buf.push('&');
        match self.peek() {
            Some(c) if c.is_ascii_alphanumeric() => {
                self.named_char_ref();
            }
            Some('#') => {
                self.pos += 1;
                self.temp_buf.push('#');
                self.numeric_char_ref();
            }
            _ => {
                self.flush_code_points_consumed_as_char_ref();
            }
        }
    }

    fn named_char_ref(&mut self) {
        let map = entity_map();
        let maxlen = max_entity_len();
        // Find the longest prefix of the remaining input that is an entity name.
        let mut candidate = String::new();
        let mut best: Option<(usize, &'static str)> = None;
        let mut i = self.pos;
        while candidate.len() < maxlen {
            match self.input.get(i) {
                Some(&c) if c.is_ascii_alphanumeric() || c == ';' => {
                    candidate.push(c);
                    i += 1;
                    if let Some(v) = map.get(candidate.as_str()) {
                        best = Some((i, v));
                    }
                    if c == ';' {
                        break;
                    }
                }
                _ => break,
            }
        }
        match best {
            Some((end, value)) => {
                let consumed: String = self.input[self.pos..end].iter().collect();
                let last_is_semicolon = consumed.ends_with(';');
                if self.in_attribute() && !last_is_semicolon {
                    let next = self.input.get(end).copied();
                    if let Some(n) = next {
                        if n == '=' || n.is_ascii_alphanumeric() {
                            // Historical reasons: flush as-is.
                            self.temp_buf.push_str(&consumed);
                            self.pos = end;
                            self.flush_code_points_consumed_as_char_ref();
                            return;
                        }
                    }
                }
                self.pos = end;
                self.temp_buf.clear();
                self.temp_buf.push_str(value);
                self.flush_code_points_consumed_as_char_ref();
            }
            None => {
                // Ambiguous ampersand: consume alphanumerics.
                self.flush_code_points_consumed_as_char_ref();
                // ambiguous ampersand state
                loop {
                    match self.peek() {
                        Some(c) if c.is_ascii_alphanumeric() => {
                            self.pos += 1;
                            if self.in_attribute() {
                                self.cur_attr_value.push(c);
                            } else {
                                self.emit_char(c);
                            }
                        }
                        _ => break,
                    }
                }
            }
        }
    }

    fn numeric_char_ref(&mut self) {
        let mut code: u32 = 0;
        let mut overflow = false;
        let hex = matches!(self.peek(), Some('x') | Some('X'));
        if hex {
            let x = self.next_char().unwrap();
            self.temp_buf.push(x);
            match self.peek() {
                Some(c) if c.is_ascii_hexdigit() => {}
                _ => {
                    self.flush_code_points_consumed_as_char_ref();
                    return;
                }
            }
            while let Some(c) = self.peek() {
                if let Some(d) = c.to_digit(16) {
                    self.pos += 1;
                    code = code.saturating_mul(16).saturating_add(d);
                    if code > 0x10FFFF {
                        overflow = true;
                    }
                } else {
                    break;
                }
            }
        } else {
            match self.peek() {
                Some(c) if c.is_ascii_digit() => {}
                _ => {
                    self.flush_code_points_consumed_as_char_ref();
                    return;
                }
            }
            while let Some(c) = self.peek() {
                if let Some(d) = c.to_digit(10) {
                    self.pos += 1;
                    code = code.saturating_mul(10).saturating_add(d);
                    if code > 0x10FFFF {
                        overflow = true;
                    }
                } else {
                    break;
                }
            }
        }
        if self.peek() == Some(';') {
            self.pos += 1;
        }
        let c = numeric_char_ref_value(if overflow { 0x110000 } else { code });
        self.temp_buf.clear();
        self.temp_buf.push(c);
        self.flush_code_points_consumed_as_char_ref();
    }

    // ---- main loop ----

    pub fn run(&mut self) {
        loop {
            if !self.step() {
                break;
            }
        }
    }

    /// Returns false when EOF has been emitted.
    fn step(&mut self) -> bool {
        use State::*;
        match self.state {
            Data => {
                match self.next_char() {
                    Some('&') => {
                        self.return_state = Data;
                        self.consume_char_ref();
                    }
                    Some('<') => self.state = TagOpen,
                    Some('\0') => self.emit_char('\0'),
                    Some(c) => self.emit_char(c),
                    None => {
                        self.emit_token(Token::Eof);
                        return false;
                    }
                }
            }
            Rcdata => match self.next_char() {
                Some('&') => {
                    self.return_state = Rcdata;
                    self.consume_char_ref();
                }
                Some('<') => self.state = RcdataLessThanSign,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            Rawtext => match self.next_char() {
                Some('<') => self.state = RawtextLessThanSign,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptData => match self.next_char() {
                Some('<') => self.state = ScriptDataLessThanSign,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            Plaintext => match self.next_char() {
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            TagOpen => match self.next_char() {
                Some('!') => self.state = MarkupDeclarationOpen,
                Some('/') => self.state = EndTagOpen,
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(false);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('?') => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                Some(_) => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Data;
                }
                None => {
                    self.emit_char('<');
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            EndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('>') => self.state = Data,
                Some(_) => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                None => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            TagName => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                Some('\0') => self.tag_name.push('\u{FFFD}'),
                Some(c) => self.tag_name.push(c.to_ascii_lowercase()),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            RcdataLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RcdataEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    if self.peek().is_some() || self.pos < self.input.len() {
                        self.reconsume();
                    } else {
                        // EOF: nothing to reconsume
                    }
                    self.state = Rcdata;
                    if self.pos > self.input.len() {
                        self.pos = self.input.len();
                    }
                }
            },
            RcdataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = RcdataEndTagName;
                }
                _ => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.reconsume_if_not_eof();
                    self.state = Rcdata;
                }
            },
            RcdataEndTagName => self.raw_end_tag_name(Rcdata),
            RawtextLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RawtextEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_if_not_eof();
                    self.state = Rawtext;
                }
            },
            RawtextEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = RawtextEndTagName;
                }
                _ => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.reconsume_if_not_eof();
                    self.state = Rawtext;
                }
            },
            RawtextEndTagName => self.raw_end_tag_name(Rawtext),
            ScriptDataLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEndTagOpen;
                }
                Some('!') => {
                    self.state = ScriptDataEscapeStart;
                    self.emit_char('<');
                    self.emit_char('!');
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_if_not_eof();
                    self.state = ScriptData;
                }
            },
            ScriptDataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = ScriptDataEndTagName;
                }
                _ => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.reconsume_if_not_eof();
                    self.state = ScriptData;
                }
            },
            ScriptDataEndTagName => self.raw_end_tag_name(ScriptData),
            ScriptDataEscapeStart => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapeStartDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStartDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscaped => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataEscapedDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataEscapedLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEscapedEndTagOpen;
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.clear();
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataDoubleEscapeStart;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_if_not_eof();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = ScriptDataEscapedEndTagName;
                }
                _ => {
                    self.emit_char('<');
                    self.emit_char('/');
                    self.reconsume_if_not_eof();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedEndTagName => self.raw_end_tag_name(ScriptDataEscaped),
            ScriptDataDoubleEscapeStart => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataDoubleEscaped;
                    } else {
                        self.state = ScriptDataEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(c.to_ascii_lowercase());
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscaped => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('\0') => self.emit_char('\u{FFFD}'),
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataDoubleEscapedDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataDoubleEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{FFFD}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            ScriptDataDoubleEscapedLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataDoubleEscapeEnd;
                    self.emit_char('/');
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapeEnd => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataEscaped;
                    } else {
                        self.state = ScriptDataDoubleEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(c.to_ascii_lowercase());
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            BeforeAttributeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') | Some('>') | None => {
                    self.reconsume_if_not_eof();
                    self.state = AfterAttributeName;
                }
                Some('=') => {
                    self.start_attr();
                    self.cur_attr_name.push('=');
                    self.state = AttributeName;
                }
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttributeName;
                }
            },
            AttributeName => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    self.check_dup_attr();
                    self.reconsume();
                    self.state = AfterAttributeName;
                }
                None => {
                    self.check_dup_attr();
                    self.state = AfterAttributeName;
                }
                Some('=') => {
                    self.check_dup_attr();
                    self.state = BeforeAttributeValue;
                }
                Some('\0') => self.cur_attr_name.push('\u{FFFD}'),
                Some(c) => self.cur_attr_name.push(c.to_ascii_lowercase()),
            },
            AfterAttributeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') => self.state = SelfClosingStartTag,
                Some('=') => self.state = BeforeAttributeValue,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttributeName;
                }
            },
            BeforeAttributeValue => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('"') => self.state = AttributeValueDoubleQuoted,
                Some('\'') => self.state = AttributeValueSingleQuoted,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = AttributeValueUnquoted;
                }
            },
            AttributeValueDoubleQuoted => match self.next_char() {
                Some('"') => self.state = AfterAttributeValueQuoted,
                Some('&') => {
                    self.return_state = AttributeValueDoubleQuoted;
                    self.consume_char_ref();
                }
                Some('\0') => self.cur_attr_value.push('\u{FFFD}'),
                Some(c) => self.cur_attr_value.push(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            AttributeValueSingleQuoted => match self.next_char() {
                Some('\'') => self.state = AfterAttributeValueQuoted,
                Some('&') => {
                    self.return_state = AttributeValueSingleQuoted;
                    self.consume_char_ref();
                }
                Some('\0') => self.cur_attr_value.push('\u{FFFD}'),
                Some(c) => self.cur_attr_value.push(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            AttributeValueUnquoted => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('&') => {
                    self.return_state = AttributeValueUnquoted;
                    self.consume_char_ref();
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                Some('\0') => self.cur_attr_value.push('\u{FFFD}'),
                Some(c) => self.cur_attr_value.push(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            AfterAttributeValueQuoted => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttributeName;
                }
            },
            SelfClosingStartTag => match self.next_char() {
                Some('>') => {
                    self.tag_self_closing = true;
                    self.state = Data;
                    self.emit_tag();
                }
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttributeName;
                }
            },
            BogusComment => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some('\0') => self.comment.push('\u{FFFD}'),
                Some(c) => self.comment.push(c),
            },
            MarkupDeclarationOpen => {
                if self.lookahead("--") {
                    self.pos += 2;
                    self.comment.clear();
                    self.state = CommentStart;
                } else if self.lookahead_ci("doctype") {
                    self.pos += 7;
                    self.state = Doctype;
                } else if self.lookahead("[CDATA[") {
                    if self.sink.adjusted_current_node_not_html() {
                        self.pos += 7;
                        self.state = CdataSection;
                    } else {
                        self.comment.clear();
                        self.comment.push_str("[CDATA[");
                        self.pos += 7;
                        self.state = BogusComment;
                    }
                } else {
                    self.comment.clear();
                    self.state = BogusComment;
                }
            }
            CommentStart => match self.next_char() {
                Some('-') => self.state = CommentStartDash,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = Comment;
                }
            },
            CommentStartDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Comment => match self.next_char() {
                Some('<') => {
                    self.comment.push('<');
                    self.state = CommentLessThanSign;
                }
                Some('-') => self.state = CommentEndDash,
                Some('\0') => self.comment.push('\u{FFFD}'),
                Some(c) => self.comment.push(c),
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            CommentLessThanSign => match self.next_char() {
                Some('!') => {
                    self.comment.push('!');
                    self.state = CommentLessThanSignBang;
                }
                Some('<') => self.comment.push('<'),
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = Comment;
                }
            },
            CommentLessThanSignBang => match self.next_char() {
                Some('-') => self.state = CommentLessThanSignBangDash,
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = Comment;
                }
            },
            CommentLessThanSignBangDash => match self.next_char() {
                Some('-') => self.state = CommentLessThanSignBangDashDash,
                _ => {
                    self.reconsume_if_not_eof();
                    self.state = CommentEndDash;
                }
            },
            CommentLessThanSignBangDashDash => {
                // '>' or EOF: reconsume in comment end state; anything else: parse error, reconsume in comment end state.
                self.reconsume_if_not_eof_peek();
                self.state = CommentEnd;
            }
            CommentEndDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEnd => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                Some('!') => self.state = CommentEndBang,
                Some('-') => self.comment.push('-'),
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.comment.push_str("--");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEndBang => match self.next_char() {
                Some('-') => {
                    self.comment.push_str("--!");
                    self.state = CommentEndDash;
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.comment.push_str("--!");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Doctype => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypeName,
                Some('>') => {
                    self.reconsume();
                    self.state = BeforeDoctypeName;
                }
                None => {
                    self.doctype = DoctypeBuilder { name: None, public_id: None, system_id: None, force_quirks: true };
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeDoctypeName;
                }
            },
            BeforeDoctypeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('\0') => {
                    self.doctype = DoctypeBuilder {
                        name: Some("\u{FFFD}".to_string()),
                        public_id: None,
                        system_id: None,
                        force_quirks: false,
                    };
                    self.state = DoctypeName;
                }
                Some('>') => {
                    self.doctype = DoctypeBuilder { name: None, public_id: None, system_id: None, force_quirks: true };
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype = DoctypeBuilder { name: None, public_id: None, system_id: None, force_quirks: true };
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(c) => {
                    self.doctype = DoctypeBuilder {
                        name: Some(c.to_ascii_lowercase().to_string()),
                        public_id: None,
                        system_id: None,
                        force_quirks: false,
                    };
                    self.state = DoctypeName;
                }
            },
            DoctypeName => match self.next_char() {
                Some(c) if is_ws(c) => self.state = AfterDoctypeName,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('\0') => self.doctype.name.get_or_insert_with(String::new).push('\u{FFFD}'),
                Some(c) => self.doctype.name.get_or_insert_with(String::new).push(c.to_ascii_lowercase()),
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            AfterDoctypeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.reconsume();
                    if self.lookahead_ci("public") {
                        self.pos += 6;
                        self.state = AfterDoctypePublicKeyword;
                    } else if self.lookahead_ci("system") {
                        self.pos += 6;
                        self.state = AfterDoctypeSystemKeyword;
                    } else {
                        self.doctype.force_quirks = true;
                        self.state = BogusDoctype;
                    }
                }
            },
            AfterDoctypePublicKeyword => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypePublicIdentifier,
                Some('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdentifierSingleQuoted;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BeforeDoctypePublicIdentifier => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = DoctypePublicIdentifierSingleQuoted;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            DoctypePublicIdentifierDoubleQuoted => match self.next_char() {
                Some('"') => self.state = AfterDoctypePublicIdentifier,
                Some('\0') => self.doctype.public_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(c) => self.doctype.public_id.get_or_insert_with(String::new).push(c),
            },
            DoctypePublicIdentifierSingleQuoted => match self.next_char() {
                Some('\'') => self.state = AfterDoctypePublicIdentifier,
                Some('\0') => self.doctype.public_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(c) => self.doctype.public_id.get_or_insert_with(String::new).push(c),
            },
            AfterDoctypePublicIdentifier => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BetweenDoctypePublicAndSystemIdentifiers,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierSingleQuoted;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BetweenDoctypePublicAndSystemIdentifiers => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierSingleQuoted;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            AfterDoctypeSystemKeyword => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypeSystemIdentifier,
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierSingleQuoted;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BeforeDoctypeSystemIdentifier => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierDoubleQuoted;
                }
                Some('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = DoctypeSystemIdentifierSingleQuoted;
                }
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            DoctypeSystemIdentifierDoubleQuoted => match self.next_char() {
                Some('"') => self.state = AfterDoctypeSystemIdentifier,
                Some('\0') => self.doctype.system_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(c) => self.doctype.system_id.get_or_insert_with(String::new).push(c),
            },
            DoctypeSystemIdentifierSingleQuoted => match self.next_char() {
                Some('\'') => self.state = AfterDoctypeSystemIdentifier,
                Some('\0') => self.doctype.system_id.get_or_insert_with(String::new).push('\u{FFFD}'),
                Some('>') => {
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(c) => self.doctype.system_id.get_or_insert_with(String::new).push(c),
            },
            AfterDoctypeSystemIdentifier => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BogusDoctype => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.emit_doctype();
                    self.emit_token(Token::Eof);
                    return false;
                }
                Some(_) => {}
            },
            CdataSection => match self.next_char() {
                Some(']') => self.state = CdataSectionBracket,
                Some(c) => self.emit_char(c),
                None => {
                    self.emit_token(Token::Eof);
                    return false;
                }
            },
            CdataSectionBracket => match self.next_char() {
                Some(']') => self.state = CdataSectionEnd,
                _ => {
                    self.emit_char(']');
                    self.reconsume_if_not_eof();
                    self.state = CdataSection;
                }
            },
            CdataSectionEnd => match self.next_char() {
                Some(']') => self.emit_char(']'),
                Some('>') => self.state = Data,
                _ => {
                    self.emit_char(']');
                    self.emit_char(']');
                    self.reconsume_if_not_eof();
                    self.state = CdataSection;
                }
            },
        }
        true
    }

    /// Reconsume the current character unless we just hit EOF.
    fn reconsume_if_not_eof(&mut self) {
        if self.pos <= self.input.len() && self.pos > 0 && self.pos - 1 < self.input.len() {
            // We consumed a real character; put it back.
            self.pos -= 1;
        }
    }

    /// For states which look at the next character without consuming it.
    fn reconsume_if_not_eof_peek(&mut self) {
        // No consumption happened; nothing to do.
    }

    /// Shared implementation of the RCDATA / RAWTEXT / script data end tag name states.
    fn raw_end_tag_name(&mut self, back: State) {
        match self.next_char() {
            Some(c) if is_ws(c) && self.is_appropriate_end_tag() => {
                self.state = State::BeforeAttributeName;
            }
            Some('/') if self.is_appropriate_end_tag() => {
                self.state = State::SelfClosingStartTag;
            }
            Some('>') if self.is_appropriate_end_tag() => {
                self.state = State::Data;
                self.emit_tag();
            }
            Some(c) if c.is_ascii_alphabetic() => {
                self.tag_name.push(c.to_ascii_lowercase());
                self.temp_buf.push(c);
            }
            _ => {
                self.emit_char('<');
                self.emit_char('/');
                self.emit_temp_buf_chars();
                self.reconsume_if_not_eof();
                self.state = back;
            }
        }
    }
}

fn numeric_char_ref_value(code: u32) -> char {
    match code {
        0x00 => '\u{FFFD}',
        0xD800..=0xDFFF => '\u{FFFD}',
        c if c > 0x10FFFF => '\u{FFFD}',
        0x80 => '\u{20AC}',
        0x82 => '\u{201A}',
        0x83 => '\u{0192}',
        0x84 => '\u{201E}',
        0x85 => '\u{2026}',
        0x86 => '\u{2020}',
        0x87 => '\u{2021}',
        0x88 => '\u{02C6}',
        0x89 => '\u{2030}',
        0x8A => '\u{0160}',
        0x8B => '\u{2039}',
        0x8C => '\u{0152}',
        0x8E => '\u{017D}',
        0x91 => '\u{2018}',
        0x92 => '\u{2019}',
        0x93 => '\u{201C}',
        0x94 => '\u{201D}',
        0x95 => '\u{2022}',
        0x96 => '\u{2013}',
        0x97 => '\u{2014}',
        0x98 => '\u{02DC}',
        0x99 => '\u{2122}',
        0x9A => '\u{0161}',
        0x9B => '\u{203A}',
        0x9C => '\u{0153}',
        0x9E => '\u{017E}',
        0x9F => '\u{0178}',
        c => char::from_u32(c).unwrap_or('\u{FFFD}'),
    }
}
