fn doctype_quirks(name: &Option<String>, public_id: &Option<String>, system_id: &Option<String>, force_quirks: bool) -> QuirksMode {
    let name_ok = name.as_deref() == Some("html");
    let pid = public_id.as_deref().map(|s| s.to_ascii_lowercase());
    let sid = system_id.as_deref().map(|s| s.to_ascii_lowercase());
    if force_quirks || !name_ok {
        return QuirksMode::Quirks;
    }
    if let Some(p) = &pid {
        if p == "-//w3o//dtd w3 html strict 3.0//en//"
            || p == "-/w3c/dtd html 4.0 transitional/en"
            || p == "html"
        {
            return QuirksMode::Quirks;
        }
        if QUIRKY_PUBLIC_PREFIXES.iter().any(|pre| p.starts_with(pre)) {
            return QuirksMode::Quirks;
        }
        if sid.is_none()
            && (p.starts_with("-//w3c//dtd html 4.01 frameset//") || p.starts_with("-//w3c//dtd html 4.01 transitional//"))
        {
            return QuirksMode::Quirks;
        }
    }
    if let Some(s) = &sid {
        if s == "http://www.ibm.com/data/dtd/v11/ibmxhtml1-transitional.dtd" {
            return QuirksMode::Quirks;
        }
    }
    // Limited quirks
    if let Some(p) = &pid {
        if p.starts_with("-//w3c//dtd xhtml 1.0 frameset//") || p.starts_with("-//w3c//dtd xhtml 1.0 transitional//") {
            return QuirksMode::LimitedQuirks;
        }
        if sid.is_some()
            && (p.starts_with("-//w3c//dtd html 4.01 frameset//") || p.starts_with("-//w3c//dtd html 4.01 transitional//"))
        {
            return QuirksMode::LimitedQuirks;
        }
    }
    QuirksMode::NoQuirks
}

enum InsertLoc {
