    /// Insert before the given node (which has a parent).
    Before(NodeRef),
}

impl TreeBuilder {
    pub fn new() -> TreeBuilder {
        TreeBuilder {
            document: NodeRef::new_document(),
            mode: Mode::Initial,
            original_mode: Mode::Initial,
            template_modes: Vec::new(),
            open: Vec::new(),
            formatting: Vec::new(),
            head: None,
            form: None,
            frameset_ok: true,
            scripting: true,
            ignore_lf: false,
            pending_table_text: Vec::new(),
            foster_parenting: false,
            quirks: QuirksMode::NoQuirks,
            raw_request: None,
        }
    }

    // ---- stack helpers ----

    fn current_node(&self) -> NodeRef {
        self.open.last().expect("open elements").clone()
    }

    fn adjusted_current_node(&self) -> Option<NodeRef> {
        // No fragment parsing: adjusted current node == current node.
        self.open.last().cloned()
    }

    fn pop(&mut self) -> Option<NodeRef> {
        self.open.pop()
    }

    fn has_in_scope(&self, local: &str, scope: Scope) -> bool {
        for node in self.open.iter().rev() {
            if is_html(node, local) {
                return true;
            }
            if in_scope_boundary(node, scope) {
                return false;
            }
        }
        false
    }

    fn has_any_in_scope(&self, locals: &[&str], scope: Scope) -> bool {
        for node in self.open.iter().rev() {
            if is_html_in(node, locals) {
                return true;
            }
            if in_scope_boundary(node, scope) {
                return false;
            }
        }
        false
    }

    fn has_node_in_scope(&self, target: &NodeRef, scope: Scope) -> bool {
        for node in self.open.iter().rev() {
            if node == target {
                return true;
            }
            if in_scope_boundary(node, scope) {
                return false;
            }
        }
        false
    }

    fn pop_until_html(&mut self, local: &str) {
        while let Some(n) = self.pop() {
            if is_html(&n, local) {
                break;
            }
        }
    }

    fn pop_until_html_in(&mut self, locals: &[&str]) {
        while let Some(n) = self.pop() {
            if is_html_in(&n, locals) {
                break;
            }
        }
    }

    fn pop_until_node(&mut self, target: &NodeRef) {
        while let Some(n) = self.pop() {
            if n == *target {
                break;
            }
        }
    }

    fn open_has_template(&self) -> bool {
        self.open.iter().any(|n| is_html(n, "template"))
    }

    fn generate_implied_end_tags(&mut self, except: Option<&str>) {
        loop {
            let cur = match self.open.last() {
                Some(c) => c.clone(),
                None => return,
            };
            if is_html_in(&cur, IMPLIED_END) {
                if let Some(ex) = except {
                    if is_html(&cur, ex) {
                        return;
                    }
                }
                self.pop();
            } else {
                return;
            }
        }
    }

    fn generate_implied_end_tags_thoroughly(&mut self) {
        loop {
            let cur = match self.open.last() {
                Some(c) => c.clone(),
                None => return,
            };
            if is_html_in(&cur, IMPLIED_END_THOROUGH) {
                self.pop();
            } else {
                return;
            }
        }
    }

    fn clear_stack_back_to_table_context(&mut self) {
        while let Some(cur) = self.open.last() {
            if is_html_in(cur, &["table", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    fn clear_stack_back_to_table_body_context(&mut self) {
        while let Some(cur) = self.open.last() {
            if is_html_in(cur, &["tbody", "tfoot", "thead", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    fn clear_stack_back_to_table_row_context(&mut self) {
        while let Some(cur) = self.open.last() {
            if is_html_in(cur, &["tr", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    fn reset_insertion_mode(&mut self) {
        let mut last = false;
        let len = self.open.len();
        for i in (0..len).rev() {
            let mut node = self.open[i].clone();
            if i == 0 {
                last = true;
                // No fragment context.
            }
            let _ = &mut node;
            let e = node.as_element().unwrap();
            if e.name.ns != NS_HTML {
                continue;
            }
            match e.name.local.as_str() {
                "select" => {
                    if !last {
                        let mut ancestor_idx = i;
                        loop {
                            if ancestor_idx == 0 {
                                break;
                            }
                            ancestor_idx -= 1;
                            let ancestor = &self.open[ancestor_idx];
                            if is_html(ancestor, "template") {
                                break;
                            }
                            if is_html(ancestor, "table") {
                                self.mode = Mode::InSelectInTable;
                                return;
                            }
                        }
                    }
                    self.mode = Mode::InSelect;
                    return;
                }
                "td" | "th" if !last => {
                    self.mode = Mode::InCell;
                    return;
                }
                "tr" => {
                    self.mode = Mode::InRow;
                    return;
                }
                "tbody" | "thead" | "tfoot" => {
                    self.mode = Mode::InTableBody;
                    return;
                }
                "caption" => {
                    self.mode = Mode::InCaption;
                    return;
                }
                "colgroup" => {
                    self.mode = Mode::InColumnGroup;
                    return;
                }
                "table" => {
                    self.mode = Mode::InTable;
                    return;
                }
                "template" => {
                    self.mode = *self.template_modes.last().unwrap_or(&Mode::InTemplate);
                    return;
                }
                "head" if !last => {
                    self.mode = Mode::InHead;
                    return;
                }
                "body" => {
                    self.mode = Mode::InBody;
                    return;
                }
                "frameset" => {
                    self.mode = Mode::InFrameset;
                    return;
                }
                "html" => {
                    self.mode = if self.head.is_none() { Mode::BeforeHead } else { Mode::AfterHead };
                    return;
                }
                _ => {}
            }
            if last {
                self.mode = Mode::InBody;
                return;
            }
        }
        self.mode = Mode::InBody;
    }

    // ---- insertion ----

    fn appropriate_insertion_location(&self, override_target: Option<NodeRef>) -> InsertLoc {
        let target = match override_target {
            Some(t) => t,
            None => self.current_node(),
        };
        if self.foster_parenting && is_html_in(&target, &["table", "tbody", "tfoot", "thead", "tr"]) {
            // Foster parenting.
            let mut last_template: Option<usize> = None;
            let mut last_table: Option<usize> = None;
            for (i, n) in self.open.iter().enumerate().rev() {
                if last_template.is_none() && is_html(n, "template") {
                    last_template = Some(i);
                }
                if last_table.is_none() && is_html(n, "table") {
                    last_table = Some(i);
                }
            }
            if let Some(ti) = last_template {
                if last_table.map_or(true, |tb| ti > tb) {
                    let tmpl = &self.open[ti];
                    let contents = tmpl.as_element().unwrap().template_contents.clone().unwrap();
                    return InsertLoc::Append(contents);
                }
            }
            match last_table {
                None => return InsertLoc::Append(self.open[0].clone()),
                Some(tb) => {
                    let table = &self.open[tb];
                    if table.parent().is_some() {
                        return InsertLoc::Before(table.clone());
                    }
                    return InsertLoc::Append(self.open[tb - 1].clone());
                }
            }
        }
        if is_html(&target, "template") {
            let contents = target.as_element().unwrap().template_contents.clone().unwrap();
            return InsertLoc::Append(contents);
        }
        InsertLoc::Append(target)
    }

    fn insert_at(loc: InsertLoc, node: NodeRef) {
        match loc {
            InsertLoc::Append(parent) => parent.append(node),
            InsertLoc::Before(sibling) => sibling.insert_before(node),
        }
    }

    fn create_element(&self, tag: &Tag, ns: &str) -> NodeRef {
        let local = if ns == NS_SVG { adjust_svg_tag_name(&tag.name).to_string() } else { tag.name.clone() };
        let attrs = build_attributes(tag, ns);
        let template_contents =
            if ns == NS_HTML && tag.name == "template" { Some(NodeRef::new_fragment()) } else { None };
        NodeRef::new_element(QualName::new(ns, &local), attrs, template_contents)
    }

    fn insert_element(&mut self, tag: &Tag, ns: &str) -> NodeRef {
        let node = self.create_element(tag, ns);
        let loc = self.appropriate_insertion_location(None);
        Self::insert_at(loc, node.clone());
        self.open.push(node.clone());
        node
    }

    fn insert_html_element(&mut self, tag: &Tag) -> NodeRef {
        self.insert_element(tag, NS_HTML)
    }

    fn insert_html_element_named(&mut self, name: &str) -> NodeRef {
        let tag = Tag { name: name.to_string(), attrs: Vec::new(), self_closing: false };
        self.insert_html_element(&tag)
    }

    fn insert_text(&mut self, text: &str) {
        if text.is_empty() {
            return;
        }
        let loc = self.appropriate_insertion_location(None);
        match loc {
            InsertLoc::Append(parent) => {
                if let Some(last) = parent.last_child() {
                    if let Some(t) = last.as_text() {
                        t.borrow_mut().push_str(text);
                        return;
                    }
                }
                if parent.as_document().is_some() {
                    return;
                }
                parent.append(NodeRef::new_text(text.to_string()));
            }
            InsertLoc::Before(sibling) => {
                if let Some(prev) = sibling.previous_sibling() {
                    if let Some(t) = prev.as_text() {
                        t.borrow_mut().push_str(text);
                        return;
                    }
                }
                sibling.insert_before(NodeRef::new_text(text.to_string()));
            }
        }
    }

    fn insert_comment(&mut self, text: String) {
        let loc = self.appropriate_insertion_location(None);
        Self::insert_at(loc, NodeRef::new_comment(text));
    }

    fn insert_comment_in(&mut self, parent: &NodeRef, text: String) {
        parent.append(NodeRef::new_comment(text));
    }

    // ---- active formatting elements ----

    fn push_formatting(&mut self, node: NodeRef, tag: Tag) {
        // Noah's Ark clause: at most 3 matching elements since last marker.
        let mut count = 0;
        let mut earliest: Option<usize> = None;
        for (i, entry) in self.formatting.iter().enumerate().rev() {
            match entry {
                FormatEntry::Marker => break,
                FormatEntry::Element(n, t) => {
                    if same_tag(n, t, &node, &tag) {
                        count += 1;
                        earliest = Some(i);
                    }
                }
            }
        }
        if count >= 3 {
            if let Some(i) = earliest {
                self.formatting.remove(i);
            }
        }
        self.formatting.push(FormatEntry::Element(node, tag));
    }

    fn clear_formatting_to_marker(&mut self) {
        while let Some(entry) = self.formatting.pop() {
            if matches!(entry, FormatEntry::Marker) {
                break;
            }
        }
    }

    fn reconstruct_formatting(&mut self) {
        if self.formatting.is_empty() {
            return;
        }
        // Step 3: last entry.
        let last_idx = self.formatting.len() - 1;
        match &self.formatting[last_idx] {
            FormatEntry::Marker => return,
            FormatEntry::Element(n, _) => {
                if self.open.contains(n) {
                    return;
                }
            }
        }
        let mut idx = last_idx;
        // Rewind.
        loop {
            if idx == 0 {
                break;
            }
            idx -= 1;
            match &self.formatting[idx] {
                FormatEntry::Marker => {
                    idx += 1;
                    break;
                }
                FormatEntry::Element(n, _) => {
                    if self.open.contains(n) {
                        idx += 1;
                        break;
                    }
                }
            }
        }
        // Create loop.
        loop {
            let tag = match &self.formatting[idx] {
                FormatEntry::Element(_, t) => t.clone(),
                FormatEntry::Marker => unreachable!(),
            };
            let new_node = self.insert_html_element(&tag);
            self.formatting[idx] = FormatEntry::Element(new_node, tag);
            if idx == self.formatting.len() - 1 {
                break;
            }
            idx += 1;
        }
    }

    fn formatting_index_of(&self, node: &NodeRef) -> Option<usize> {
        self.formatting.iter().position(|e| match e {
            FormatEntry::Element(n, _) => n == node,
            _ => false,
        })
    }

    /// Find an active formatting element between the end of the list and the
    /// last marker with the given tag name.
    fn find_formatting(&self, local: &str) -> Option<(usize, NodeRef)> {
        for (i, entry) in self.formatting.iter().enumerate().rev() {
            match entry {
                FormatEntry::Marker => return None,
                FormatEntry::Element(n, _) => {
                    if is_html(n, local) {
                        return Some((i, n.clone()));
                    }
                }
            }
        }
        None
    }

    // ---- token processing ----

    fn set_quirks(&mut self, q: QuirksMode) {
        self.quirks = q;
        if let Some(d) = self.document.as_document() {
            *d.quirks_mode.borrow_mut() = q;
        }
    }

    fn process(&mut self, token: Token, mode: Mode) {
        // Dispatch loop with explicit reprocessing.
        let mut token = token;
        let mut mode = mode;
        loop {
            match self.step(token, mode) {
                Step::Done => return,
                Step::Reprocess(t) => {
                    token = t;
                    mode = self.mode;
                }
                Step::ReprocessIn(t, m) => {
                    token = t;
                    mode = m;
                }
            }
        }
    }

    fn should_use_foreign(&self, token: &Token) -> bool {
        let acn = match self.adjusted_current_node() {
            Some(n) => n,
            None => return false,
        };
        let e = acn.as_element().unwrap();
        if e.name.ns == NS_HTML {
            return false;
        }
        if is_mathml_text_integration_point(&acn) {
            match token {
                Token::StartTag(t) if t.name != "mglyph" && t.name != "malignmark" => return false,
                Token::Characters(_) => return false,
                _ => {}
            }
        }
        if e.name.ns == NS_MATHML && e.name.local == "annotation-xml" {
            if let Token::StartTag(t) = token {
                if t.name == "svg" {
                    return false;
                }
            }
        }
        if is_html_integration_point(&acn) {
            match token {
                Token::StartTag(_) | Token::Characters(_) => return false,
                _ => {}
            }
        }
        if matches!(token, Token::Eof) {
            return false;
        }
        true
    }
}

enum Step {
    Done,
    Reprocess(Token),
    ReprocessIn(Token, Mode),
}

fn same_tag(n: &NodeRef, t: &Tag, node: &NodeRef, tag: &Tag) -> bool {
    let a = n.as_element().unwrap();
    let b = node.as_element().unwrap();
    if a.name != b.name {
        return false;
    }
    // Compare attributes (name, value) sets.
    let mut aa: Vec<(&String, &String)> = t.attrs.iter().map(|(k, v)| (k, v)).collect();
    let mut bb: Vec<(&String, &String)> = tag.attrs.iter().map(|(k, v)| (k, v)).collect();
    aa.sort();
    bb.sort();
    aa == bb
}

impl TokenSink for TreeBuilder {
    fn process_token(&mut self, token: Token) -> SinkResult {
        self.raw_request = None;
        // Handle the "ignore LF after <pre>" rule.
        let token = if self.ignore_lf {
            self.ignore_lf = false;
            match token {
                Token::Characters(s) if s.starts_with('\n') => {
                    let rest: String = s[1..].to_string();
                    if rest.is_empty() {
                        return SinkResult::Continue;
                    }
                    Token::Characters(rest)
                }
                t => t,
            }
        } else {
            token
        };
        let mode = self.mode;
        if self.should_use_foreign(&token) {
            self.process_foreign(token);
        } else {
            self.process(token, mode);
        }
        match self.raw_request.take() {
            Some(k) => SinkResult::Raw(k),
            None => SinkResult::Continue,
        }
    }

    fn adjusted_current_node_not_html(&self) -> bool {
        match self.adjusted_current_node() {
            Some(n) => n.as_element().unwrap().name.ns != NS_HTML,
            None => false,
        }
    }
}

