//! HTML tree construction following the WHATWG HTML living standard.

use crate::dom::*;
use crate::tokenizer::{RawKind, SinkResult, Tag, Token, TokenSink};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    Initial,
    BeforeHtml,
    BeforeHead,
    InHead,
    InHeadNoscript,
    AfterHead,
    InBody,
    Text,
    InTable,
    InTableText,
    InCaption,
    InColumnGroup,
    InTableBody,
    InRow,
    InCell,
    InSelect,
    InSelectInTable,
    InTemplate,
    AfterBody,
    InFrameset,
    AfterFrameset,
    AfterAfterBody,
    AfterAfterFrameset,
}

#[derive(Clone)]
enum FormatEntry {
    Marker,
    Element(NodeRef, Tag),
}

pub struct TreeBuilder {
    pub document: NodeRef,
    mode: Mode,
    original_mode: Mode,
    template_modes: Vec<Mode>,
    open: Vec<NodeRef>,
    formatting: Vec<FormatEntry>,
    head: Option<NodeRef>,
    form: Option<NodeRef>,
    frameset_ok: bool,
    scripting: bool,
    ignore_lf: bool,
    pending_table_text: Vec<String>,
    foster_parenting: bool,
    quirks: QuirksMode,
    /// Pending request to switch the tokenizer state.
    raw_request: Option<RawKind>,
}

const SPECIAL_HTML: &[&str] = &[
    "address", "applet", "area", "article", "aside", "base", "basefont", "bgsound", "blockquote", "body", "br",
    "button", "caption", "center", "col", "colgroup", "dd", "details", "dir", "div", "dl", "dt", "embed",
    "fieldset", "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6",
    "head", "header", "hgroup", "hr", "html", "iframe", "img", "input", "keygen", "li", "link", "listing", "main",
    "marquee", "menu", "meta", "nav", "noembed", "noframes", "noscript", "object", "ol", "p", "param", "plaintext",
    "pre", "script", "section", "select", "source", "style", "summary", "table", "tbody", "td", "template",
    "textarea", "tfoot", "th", "thead", "title", "tr", "track", "ul", "wbr", "xmp",
];

const FORMATTING: &[&str] =
    &["a", "b", "big", "code", "em", "font", "i", "nobr", "s", "small", "strike", "strong", "tt", "u"];

const IMPLIED_END: &[&str] = &["dd", "dt", "li", "optgroup", "option", "p", "rb", "rp", "rt", "rtc"];
const IMPLIED_END_THOROUGH: &[&str] = &[
    "caption", "colgroup", "dd", "dt", "li", "optgroup", "option", "p", "rb", "rp", "rt", "rtc", "tbody", "td",
    "tfoot", "th", "thead", "tr",
];

const HEADINGS: &[&str] = &["h1", "h2", "h3", "h4", "h5", "h6"];

fn is_ws_str(s: &str) -> bool {
    s.chars().all(|c| matches!(c, '\t' | '\n' | '\x0C' | '\r' | ' '))
}

fn name_of(node: &NodeRef) -> &QualName {
    &node.as_element().expect("element").name
}

fn is_html(node: &NodeRef, local: &str) -> bool {
    match node.as_element() {
        Some(e) => e.name.ns == NS_HTML && e.name.local == local,
        None => false,
    }
}

fn is_html_in(node: &NodeRef, locals: &[&str]) -> bool {
    match node.as_element() {
        Some(e) => e.name.ns == NS_HTML && locals.contains(&e.name.local.as_str()),
        None => false,
    }
}

fn is_special(node: &NodeRef) -> bool {
    let e = match node.as_element() {
        Some(e) => e,
        None => return false,
    };
    let l = e.name.local.as_str();
    match e.name.ns.as_str() {
        NS_HTML => SPECIAL_HTML.contains(&l),
        NS_MATHML => matches!(l, "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml"),
        NS_SVG => matches!(l, "foreignObject" | "desc" | "title"),
        _ => false,
    }
}

fn is_mathml_text_integration_point(node: &NodeRef) -> bool {
    match node.as_element() {
        Some(e) => e.name.ns == NS_MATHML && matches!(e.name.local.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext"),
        None => false,
    }
}

fn is_html_integration_point(node: &NodeRef) -> bool {
    let e = match node.as_element() {
        Some(e) => e,
        None => return false,
    };
    if e.name.ns == NS_MATHML && e.name.local == "annotation-xml" {
        let attrs = e.attributes.borrow();
        if let Some(enc) = attrs.get("encoding") {
            let enc = enc.to_ascii_lowercase();
            return enc == "text/html" || enc == "application/xhtml+xml";
        }
        return false;
    }
    e.name.ns == NS_SVG && matches!(e.name.local.as_str(), "foreignObject" | "desc" | "title")
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Scope {
    Default,
    ListItem,
    Button,
    Table,
    Select,
}

fn in_scope_boundary(node: &NodeRef, scope: Scope) -> bool {
    let e = match node.as_element() {
        Some(e) => e,
        None => return false,
    };
    let l = e.name.local.as_str();
    match scope {
        Scope::Select => {
            // All elements except optgroup and option are boundaries.
            !(e.name.ns == NS_HTML && (l == "optgroup" || l == "option"))
        }
        Scope::Table => e.name.ns == NS_HTML && matches!(l, "html" | "table" | "template"),
        _ => {
            let default = match e.name.ns.as_str() {
                NS_HTML => matches!(l, "applet" | "caption" | "html" | "table" | "td" | "th" | "marquee" | "object" | "template"),
                NS_MATHML => matches!(l, "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml"),
                NS_SVG => matches!(l, "foreignObject" | "desc" | "title"),
                _ => false,
            };
            if default {
                return true;
            }
            match scope {
                Scope::ListItem => e.name.ns == NS_HTML && matches!(l, "ol" | "ul"),
                Scope::Button => e.name.ns == NS_HTML && l == "button",
                _ => false,
            }
        }
    }
}

// ---- foreign name/attribute adjustments ----

