/// Returns (prefix, local, namespace) for a foreign attribute name.
fn adjust_foreign_attr(name: &str) -> (Option<&str>, &str, &str) {
    match name {
        "xlink:actuate" | "xlink:arcrole" | "xlink:href" | "xlink:role" | "xlink:show" | "xlink:title" | "xlink:type" => {
            (Some("xlink"), &name[6..], NS_XLINK)
        }
        "xml:lang" | "xml:space" => (Some("xml"), &name[4..], NS_XML),
        "xmlns" => (None, "xmlns", NS_XMLNS),
        "xmlns:xlink" => (Some("xmlns"), "xlink", NS_XMLNS),
        other => (None, other, ""),
    }
}

fn build_attributes(tag: &Tag, ns: &str) -> Attributes {
    let mut attrs = Attributes::default();
    for (name, value) in &tag.attrs {
        let (prefix, local, attr_ns) = if ns == NS_HTML {
            (None, name.as_str(), "")
        } else {
            let adjusted: &str = if ns == NS_SVG {
                adjust_svg_attr_name(name)
            } else if ns == NS_MATHML && name == "definitionurl" {
                "definitionURL"
            } else {
                name
            };
            let (p, l, n) = adjust_foreign_attr(adjusted);
            (p, l, n)
        };
        let key = AttrName { ns: attr_ns.to_string(), local: local.to_string() };
        if !attrs.map.contains_key(&key) {
            attrs.map.insert(key, Attribute { prefix: prefix.map(|s| s.to_string()), value: value.clone() });
        }
    }
    attrs
}

