    }

    fn in_body_end_tag(&mut self, tag: Tag) -> Step {
        match tag.name.as_str() {
            "template" => self.mode_in_head(Token::EndTag(tag)),
            "body" => {
                if !self.has_in_scope("body", Scope::Default) {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Done
            }
            "html" => {
                if !self.has_in_scope("body", Scope::Default) {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Reprocess(Token::EndTag(tag))
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details" | "dialog" | "dir"
            | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "listing"
            | "main" | "menu" | "nav" | "ol" | "pre" | "section" | "summary" | "ul" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html(&tag.name);
                Step::Done
            }
            "form" => {
                if !self.open_has_template() {
                    let node = self.form.take();
                    let node = match node {
                        Some(n) => n,
                        None => return Step::Done,
                    };
                    if !self.has_node_in_scope(&node, Scope::Default) {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags(None);
                    if let Some(pos) = self.open.iter().position(|n| *n == node) {
                        self.open.remove(pos);
                    }
                } else {
                    if !self.has_in_scope("form", Scope::Default) {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags(None);
                    self.pop_until_html("form");
                }
                Step::Done
            }
            "p" => {
                if !self.has_in_scope("p", Scope::Button) {
                    self.insert_html_element_named("p");
                }
                self.close_p_element();
                Step::Done
            }
            "li" => {
                if !self.has_in_scope("li", Scope::ListItem) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some("li"));
                self.pop_until_html("li");
                Step::Done
            }
            "dd" | "dt" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some(&tag.name));
                self.pop_until_html(&tag.name);
                Step::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if !self.has_any_in_scope(HEADINGS, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html_in(HEADINGS);
                Step::Done
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small" | "strike" | "strong" | "tt"
            | "u" => {
                self.adoption_agency(&tag.name);
                Step::Done
            }
            "applet" | "marquee" | "object" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html(&tag.name);
                self.clear_formatting_to_marker();
                Step::Done
            }
            "br" => {
                let t = Tag { name: "br".to_string(), attrs: Vec::new(), self_closing: false };
                self.in_body_start_tag(t)
            }
            _ => {
                self.any_other_end_tag(&tag.name);
                Step::Done
            }
        }
    }

    fn any_other_end_tag(&mut self, name: &str) {
        let mut i = self.open.len();
        loop {
            if i == 0 {
                return;
            }
            i -= 1;
            let node = self.open[i].clone();
            if is_html(&node, name) {
                self.generate_implied_end_tags(Some(name));
                // Pop until node popped.
                while self.open.len() > i {
                    self.pop();
                }
                return;
            }
            if is_special(&node) {
                return;
            }
        }
    }

    /// The adoption agency algorithm.
    fn adoption_agency(&mut self, subject: &str) {
        // Step 1.
        let cur = self.current_node();
        if is_html(&cur, subject) && self.formatting_index_of(&cur).is_none() {
            self.pop();
            return;
        }
        let mut outer = 0;
        while outer < 8 {
            outer += 1;
            // Step 4.3: formatting element.
            let (fmt_idx, fmt_elem) = match self.find_formatting(subject) {
                Some(x) => x,
                None => {
                    self.any_other_end_tag(subject);
                    return;
                }
            };
            // 4.4: if not in stack of open elements.
            let stack_pos = match self.open.iter().position(|n| *n == fmt_elem) {
                Some(p) => p,
                None => {
                    self.formatting.remove(fmt_idx);
                    return;
                }
            };
            // 4.5: in stack but not in scope.
            if !self.has_node_in_scope(&fmt_elem, Scope::Default) {
                return;
            }
            // 4.6: parse error if not current node (ignored).
            // 4.7: furthest block.
            let mut furthest_block: Option<(usize, NodeRef)> = None;
            for i in (stack_pos + 1)..self.open.len() {
                if is_special(&self.open[i]) {
                    furthest_block = Some((i, self.open[i].clone()));
                    break;
                }
            }
            // 4.8.
            let (fb_pos, furthest_block) = match furthest_block {
                Some(x) => x,
                None => {
                    while self.open.len() > stack_pos {
                        self.pop();
                    }
                    self.formatting.remove(fmt_idx);
                    return;
                }
            };
            // 4.9: common ancestor.
            let common_ancestor = self.open[stack_pos - 1].clone();
            // 4.10: bookmark.
            let mut bookmark = fmt_idx;
            // 4.11.
            let mut node_pos = fb_pos;
            let mut node = furthest_block.clone();
            let mut last_node = furthest_block.clone();
            let mut inner = 0;
            loop {
                inner += 1;
                // 4.13.3: node = element immediately above node in the stack
                node_pos -= 1;
                node = self.open[node_pos].clone();
                // 4.13.4
                if node == fmt_elem {
                    break;
                }
                // 4.13.5
                let node_fmt_idx = self.formatting_index_of(&node);
                if inner > 3 {
                    if let Some(fi) = node_fmt_idx {
                        self.formatting.remove(fi);
                        if fi < bookmark {
                            bookmark -= 1;
                        }
                    }
                    self.open.remove(node_pos);
                    continue;
                }
                // 4.13.6
                let node_fmt_idx = match node_fmt_idx {
                    Some(fi) => fi,
                    None => {
                        self.open.remove(node_pos);
                        continue;
                    }
                };
                // 4.13.7: create element for the token for which node was created.
                let tag = match &self.formatting[node_fmt_idx] {
                    FormatEntry::Element(_, t) => t.clone(),
                    _ => unreachable!(),
                };
                let new_elem = self.create_element(&tag, NS_HTML);
                self.formatting[node_fmt_idx] = FormatEntry::Element(new_elem.clone(), tag);
                self.open[node_pos] = new_elem.clone();
                node = new_elem;
                // 4.13.8
                if last_node == furthest_block {
                    bookmark = node_fmt_idx + 1;
                }
                // 4.13.9
                node.append(last_node.clone());
                // 4.13.10
                last_node = node.clone();
            }
            let _ = node;
            // 4.14: insert last_node at appropriate place for inserting a node with common_ancestor as override.
            let loc = self.appropriate_insertion_location(Some(common_ancestor.clone()));
            Self::insert_at(loc, last_node.clone());
            // 4.15
            let tag = match &self.formatting[fmt_idx] {
                FormatEntry::Element(_, t) => t.clone(),
                _ => unreachable!(),
            };
            let new_elem = self.create_element(&tag, NS_HTML);
            // 4.16: move all children of furthest block to new_elem.
            let mut children: Vec<NodeRef> = furthest_block.children().collect();
            for c in children.drain(..) {
                new_elem.append(c);
            }
            // 4.17
            furthest_block.append(new_elem.clone());
            // 4.18: remove fmt_elem from formatting list, insert new_elem at bookmark.
            // Recompute fmt_idx (may have shifted).
            let cur_fmt_idx = self.formatting_index_of(&fmt_elem).unwrap();
            self.formatting.remove(cur_fmt_idx);
            if cur_fmt_idx < bookmark {
                bookmark -= 1;
            }
            if bookmark > self.formatting.len() {
                bookmark = self.formatting.len();
            }
            self.formatting.insert(bookmark, FormatEntry::Element(new_elem.clone(), tag));
            // 4.19: remove fmt_elem from stack; insert new_elem immediately below furthest block.
            let fpos = self.open.iter().position(|n| *n == fmt_elem).unwrap();
            self.open.remove(fpos);
            let fbpos = self.open.iter().position(|n| *n == furthest_block).unwrap();
            self.open.insert(fbpos + 1, new_elem);
        }
    }

    // ---- text ----
    fn mode_text(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                self.insert_text(&s);
                Step::Done
            }
            Token::Eof => {
                self.pop();
                self.mode = self.original_mode;
                Step::Reprocess(Token::Eof)
            }
            Token::EndTag(_) => {
                self.pop();
                self.mode = self.original_mode;
                Step::Done
            }
            _ => Step::Done,
        }
    }

    // ---- in table ----
    fn mode_in_table(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(_)
                if is_html_in(&self.current_node(), &["table", "tbody", "tfoot", "thead", "tr"]) =>
            {
                self.pending_table_text.clear();
                self.original_mode = self.mode;
                self.mode = Mode::InTableText;
                Step::Reprocess(token)
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "caption" => {
                    self.clear_stack_back_to_table_context();
                    self.formatting.push(FormatEntry::Marker);
                    self.insert_html_element(tag);
                    self.mode = Mode::InCaption;
                    Step::Done
                }
                "colgroup" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element(tag);
                    self.mode = Mode::InColumnGroup;
                    Step::Done
                }
                "col" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element_named("colgroup");
                    self.mode = Mode::InColumnGroup;
                    Step::Reprocess(token)
                }
                "tbody" | "tfoot" | "thead" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element(tag);
                    self.mode = Mode::InTableBody;
                    Step::Done
                }
                "td" | "th" | "tr" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element_named("tbody");
                    self.mode = Mode::InTableBody;
                    Step::Reprocess(token)
                }
                "table" => {
                    if !self.has_in_scope("table", Scope::Table) {
                        return Step::Done;
                    }
                    self.pop_until_html("table");
                    self.reset_insertion_mode();
                    Step::Reprocess(token)
                }
                "style" | "script" | "template" => self.mode_in_head(token),
                "input" => {
                    let hidden = tag
                        .attrs
                        .iter()
                        .find(|(k, _)| k == "type")
                        .map_or(false, |(_, v)| v.eq_ignore_ascii_case("hidden"));
                    if !hidden {
                        return self.in_table_anything_else(token);
                    }
                    self.insert_html_element(tag);
                    self.pop();
                    Step::Done
                }
                "form" => {
                    if self.open_has_template() || self.form.is_some() {
                        return Step::Done;
                    }
                    let node = self.insert_html_element(tag);
                    self.form = Some(node);
                    self.pop();
                    Step::Done
                }
                _ => self.in_table_anything_else(token),
            },
            Token::EndTag(ref tag) => match tag.name.as_str() {
                "table" => {
                    if !self.has_in_scope("table", Scope::Table) {
                        return Step::Done;
                    }
                    self.pop_until_html("table");
                    self.reset_insertion_mode();
                    Step::Done
                }
                "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead"
                | "tr" => Step::Done,
                "template" => self.mode_in_head(token),
                _ => self.in_table_anything_else(token),
            },
            Token::Eof => self.mode_in_body(token),
            Token::Characters(_) => self.in_table_anything_else(token),
        }
    }

    fn in_table_anything_else(&mut self, token: Token) -> Step {
        self.foster_parenting = true;
        let r = self.mode_in_body(token);
        self.foster_parenting = false;
        // Any reprocess requested by in-body rules must happen without foster parenting
        // (the spec re-dispatches in the new mode anyway).
        r
    }

    // ---- in table text ----
    fn mode_in_table_text(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    return Step::Done;
                }
                self.pending_table_text.push(s);
                Step::Done
            }
            t => {
                let pending = std::mem::take(&mut self.pending_table_text);
                if pending.iter().any(|s| !is_ws_str(s)) {
                    for s in pending {
                        self.foster_parenting = true;
                        let _ = self.mode_in_body(Token::Characters(s));
                        self.foster_parenting = false;
                    }
                } else {
                    for s in pending {
                        self.insert_text(&s);
                    }
                }
                self.mode = self.original_mode;
                Step::Reprocess(t)
            }
        }
    }

    // ---- in caption ----
    fn mode_in_caption(&mut self, token: Token) -> Step {
        match token {
            Token::EndTag(ref tag) if tag.name == "caption" => {
                if !self.has_in_scope("caption", Scope::Table) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html("caption");
                self.clear_formatting_to_marker();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::StartTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                self.caption_close_and_reprocess(token)
            }
            Token::EndTag(ref tag) if tag.name == "table" => self.caption_close_and_reprocess(token),
            Token::EndTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "body" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                Step::Done
            }
            t => self.mode_in_body(t),
        }
    }

    fn caption_close_and_reprocess(&mut self, token: Token) -> Step {
        if !self.has_in_scope("caption", Scope::Table) {
            return Step::Done;
        }
        self.generate_implied_end_tags(None);
        self.pop_until_html("caption");
        self.clear_formatting_to_marker();
        self.mode = Mode::InTable;
        Step::Reprocess(token)
    }

    // ---- in column group ----
    fn mode_in_column_group(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => {
                self.insert_text(s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::StartTag(ref tag) if tag.name == "col" => {
                self.insert_html_element(tag);
                self.pop();
                Step::Done
            }
            Token::EndTag(ref tag) if tag.name == "colgroup" => {
                if !is_html(&self.current_node(), "colgroup") {
                    return Step::Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::EndTag(ref tag) if tag.name == "col" => Step::Done,
            Token::StartTag(ref tag) if tag.name == "template" => self.mode_in_head(token),
            Token::EndTag(ref tag) if tag.name == "template" => self.mode_in_head(token),
            Token::Eof => self.mode_in_body(token),
            t => {
                if !is_html(&self.current_node(), "colgroup") {
                    return Step::Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Step::Reprocess(t)
            }
        }
    }

    // ---- in table body ----
    fn mode_in_table_body(&mut self, token: Token) -> Step {
        match token {
            Token::StartTag(ref tag) if tag.name == "tr" => {
                self.clear_stack_back_to_table_body_context();
                self.insert_html_element(tag);
                self.mode = Mode::InRow;
                Step::Done
            }
            Token::StartTag(ref tag) if matches!(tag.name.as_str(), "th" | "td") => {
                self.clear_stack_back_to_table_body_context();
                self.insert_html_element_named("tr");
                self.mode = Mode::InRow;
                Step::Reprocess(token)
            }
            Token::EndTag(ref tag) if matches!(tag.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.has_in_scope(&tag.name, Scope::Table) {
                    return Step::Done;
                }
                self.clear_stack_back_to_table_body_context();
                self.pop();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::StartTag(ref tag)
                if matches!(tag.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead") =>
            {
                self.table_body_close_and_reprocess(token)
            }
            Token::EndTag(ref tag) if tag.name == "table" => self.table_body_close_and_reprocess(token),
            Token::EndTag(ref tag)
                if matches!(tag.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" | "tr") =>
            {
                Step::Done
            }
            t => self.mode_in_table(t),
        }
    }

    fn table_body_close_and_reprocess(&mut self, token: Token) -> Step {
        if !self.has_any_in_scope(&["tbody", "thead", "tfoot"], Scope::Table) {
            return Step::Done;
        }
        self.clear_stack_back_to_table_body_context();
        self.pop();
        self.mode = Mode::InTable;
        Step::Reprocess(token)
    }

    // ---- in row ----
    fn mode_in_row(&mut self, token: Token) -> Step {
        match token {
            Token::StartTag(ref tag) if matches!(tag.name.as_str(), "th" | "td") => {
                self.clear_stack_back_to_table_row_context();
                self.insert_html_element(tag);
                self.mode = Mode::InCell;
                self.formatting.push(FormatEntry::Marker);
                Step::Done
            }
            Token::EndTag(ref tag) if tag.name == "tr" => {
                if !self.has_in_scope("tr", Scope::Table) {
                    return Step::Done;
                }
                self.clear_stack_back_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Step::Done
            }
            Token::StartTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr"
                ) =>
            {
                self.row_close_and_reprocess(token)
            }
            Token::EndTag(ref tag) if tag.name == "table" => self.row_close_and_reprocess(token),
            Token::EndTag(ref tag) if matches!(tag.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.has_in_scope(&tag.name, Scope::Table) {
                    return Step::Done;
                }
                if !self.has_in_scope("tr", Scope::Table) {
                    return Step::Done;
                }
                self.clear_stack_back_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Step::Reprocess(token)
            }
            Token::EndTag(ref tag)
                if matches!(tag.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th") =>
            {
                Step::Done
            }
            t => self.mode_in_table(t),
        }
    }

    fn row_close_and_reprocess(&mut self, token: Token) -> Step {
        if !self.has_in_scope("tr", Scope::Table) {
            return Step::Done;
        }
        self.clear_stack_back_to_table_row_context();
        self.pop();
        self.mode = Mode::InTableBody;
        Step::Reprocess(token)
    }

    // ---- in cell ----
    fn mode_in_cell(&mut self, token: Token) -> Step {
        match token {
            Token::EndTag(ref tag) if matches!(tag.name.as_str(), "td" | "th") => {
                if !self.has_in_scope(&tag.name, Scope::Table) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html(&tag.name);
                self.clear_formatting_to_marker();
                self.mode = Mode::InRow;
                Step::Done
            }
            Token::StartTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                if !self.has_any_in_scope(&["td", "th"], Scope::Table) {
                    return Step::Done;
                }
                self.close_cell();
                Step::Reprocess(token)
            }
            Token::EndTag(ref tag) if matches!(tag.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html") => {
                Step::Done
            }
            Token::EndTag(ref tag) if matches!(tag.name.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") => {
                if !self.has_in_scope(&tag.name, Scope::Table) {
                    return Step::Done;
                }
                self.close_cell();
                Step::Reprocess(token)
            }
            t => self.mode_in_body(t),
        }
    }

    fn close_cell(&mut self) {
        self.generate_implied_end_tags(None);
        self.pop_until_html_in(&["td", "th"]);
        self.clear_formatting_to_marker();
        self.mode = Mode::InRow;
    }

    // ---- in select ----
    fn mode_in_select(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    return Step::Done;
                }
                self.insert_text(&s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "html" => self.mode_in_body(token),
                "option" => {
                    if is_html(&self.current_node(), "option") {
                        self.pop();
                    }
                    self.insert_html_element(tag);
                    Step::Done
                }
                "optgroup" => {
                    if is_html(&self.current_node(), "option") {
                        self.pop();
                    }
                    if is_html(&self.current_node(), "optgroup") {
                        self.pop();
                    }
                    self.insert_html_element(tag);
                    Step::Done
                }
                "select" => {
                    if !self.has_in_scope("select", Scope::Select) {
                        return Step::Done;
                    }
                    self.pop_until_html("select");
                    self.reset_insertion_mode();
                    Step::Done
                }
                "input" | "keygen" | "textarea" => {
                    if !self.has_in_scope("select", Scope::Select) {
                        return Step::Done;
                    }
                    self.pop_until_html("select");
                    self.reset_insertion_mode();
                    Step::Reprocess(token)
                }
                "script" | "template" => self.mode_in_head(token),
                _ => Step::Done,
            },
            Token::EndTag(ref tag) => match tag.name.as_str() {
                "optgroup" => {
                    let len = self.open.len();
                    if is_html(&self.current_node(), "option") && len >= 2 && is_html(&self.open[len - 2], "optgroup")
                    {
                        self.pop();
                    }
                    if is_html(&self.current_node(), "optgroup") {
                        self.pop();
                    }
                    Step::Done
                }
                "option" => {
                    if is_html(&self.current_node(), "option") {
                        self.pop();
                    }
                    Step::Done
                }
                "select" => {
                    if !self.has_in_scope("select", Scope::Select) {
                        return Step::Done;
                    }
                    self.pop_until_html("select");
                    self.reset_insertion_mode();
                    Step::Done
                }
                "template" => self.mode_in_head(token),
                _ => Step::Done,
            },
            Token::Eof => self.mode_in_body(token),
        }
    }

    // ---- in select in table ----
    fn mode_in_select_in_table(&mut self, token: Token) -> Step {
        match token {
            Token::StartTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th"
                ) =>
            {
                self.pop_until_html("select");
                self.reset_insertion_mode();
                Step::Reprocess(token)
            }
            Token::EndTag(ref tag)
                if matches!(
                    tag.name.as_str(),
                    "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th"
                ) =>
            {
                if !self.has_in_scope(&tag.name, Scope::Table) {
                    return Step::Done;
                }
                self.pop_until_html("select");
                self.reset_insertion_mode();
                Step::Reprocess(token)
            }
            t => self.mode_in_select(t),
        }
    }

    // ---- in template ----
    fn mode_in_template(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(_) | Token::Comment(_) | Token::Doctype { .. } => self.mode_in_body(token),
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
                | "title" => self.mode_in_head(token),
                "caption" | "colgroup" | "tbody" | "tfoot" | "thead" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InTable);
                    self.mode = Mode::InTable;
                    Step::Reprocess(token)
                }
                "col" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InColumnGroup);
                    self.mode = Mode::InColumnGroup;
                    Step::Reprocess(token)
                }
                "tr" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InTableBody);
                    self.mode = Mode::InTableBody;
                    Step::Reprocess(token)
                }
                "td" | "th" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InRow);
                    self.mode = Mode::InRow;
                    Step::Reprocess(token)
                }
                _ => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InBody);
                    self.mode = Mode::InBody;
                    Step::Reprocess(token)
                }
            },
            Token::EndTag(ref tag) if tag.name == "template" => self.mode_in_head(token),
            Token::EndTag(_) => Step::Done,
            Token::Eof => {
                if !self.open_has_template() {
                    return Step::Done;
                }
                self.pop_until_html("template");
                self.clear_formatting_to_marker();
                self.template_modes.pop();
                self.reset_insertion_mode();
                Step::Reprocess(Token::Eof)
            }
        }
    }

    // ---- after body ----
    fn mode_after_body(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => self.mode_in_body(token),
            Token::Comment(c) => {
                let html = self.open[0].clone();
                self.insert_comment_in(&html, c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::EndTag(ref tag) if tag.name == "html" => {
                self.mode = Mode::AfterAfterBody;
                Step::Done
            }
            Token::Eof => Step::Done,
            t => {
                self.mode = Mode::InBody;
                Step::Reprocess(t)
            }
        }
    }

    // ---- in frameset ----
    fn mode_in_frameset(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => {
                self.insert_text(s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "html" => self.mode_in_body(token),
                "frameset" => {
                    self.insert_html_element(tag);
                    Step::Done
                }
                "frame" => {
                    self.insert_html_element(tag);
                    self.pop();
                    Step::Done
                }
                "noframes" => self.mode_in_head(token),
                _ => Step::Done,
            },
            Token::EndTag(ref tag) if tag.name == "frameset" => {
                if is_html(&self.current_node(), "html") {
                    return Step::Done;
                }
                self.pop();
                if !is_html(&self.current_node(), "frameset") {
                    self.mode = Mode::AfterFrameset;
                }
                Step::Done
            }
            Token::Eof => Step::Done,
            _ => Step::Done,
        }
    }

    // ---- after frameset ----
    fn mode_after_frameset(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => {
                self.insert_text(s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::EndTag(ref tag) if tag.name == "html" => {
                self.mode = Mode::AfterAfterFrameset;
                Step::Done
            }
            Token::StartTag(ref tag) if tag.name == "noframes" => self.mode_in_head(token),
            _ => Step::Done,
        }
    }

    // ---- after after body ----
    fn mode_after_after_body(&mut self, token: Token) -> Step {
        match token {
            Token::Comment(c) => {
                self.insert_comment_in(&self.document.clone(), c);
                Step::Done
            }
            Token::Doctype { .. } => self.mode_in_body(token),
            Token::Characters(ref s) if is_ws_str(s) => self.mode_in_body(token),
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::Eof => Step::Done,
            t => {
                self.mode = Mode::InBody;
                Step::Reprocess(t)
            }
        }
    }

    // ---- after after frameset ----
    fn mode_after_after_frameset(&mut self, token: Token) -> Step {
        match token {
            Token::Comment(c) => {
                self.insert_comment_in(&self.document.clone(), c);
                Step::Done
            }
            Token::Doctype { .. } => self.mode_in_body(token),
            Token::Characters(ref s) if is_ws_str(s) => self.mode_in_body(token),
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::StartTag(ref tag) if tag.name == "noframes" => self.mode_in_head(token),
            _ => Step::Done,
        }
    }

    // ---- foreign content ----
    fn process_foreign(&mut self, token: Token) {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    self.insert_text("\u{FFFD}");
                } else {
                    if !is_ws_str(&s) {
                        self.frameset_ok = false;
                    }
                    self.insert_text(&s);
                }
            }
            Token::Comment(c) => self.insert_comment(c),
            Token::Doctype { .. } => {}
            Token::StartTag(tag) => {
                let breakout = match tag.name.as_str() {
                    "b" | "big" | "blockquote" | "body" | "br" | "center" | "code" | "dd" | "div" | "dl" | "dt"
                    | "em" | "embed" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "head" | "hr" | "i" | "img" | "li"
                    | "listing" | "menu" | "meta" | "nobr" | "ol" | "p" | "pre" | "ruby" | "s" | "small" | "span"
                    | "strong" | "strike" | "sub" | "sup" | "table" | "tt" | "u" | "ul" | "var" => true,
                    "font" => tag.attrs.iter().any(|(k, _)| matches!(k.as_str(), "color" | "face" | "size")),
                    _ => false,
                };
                if breakout {
                    // Pop until HTML element, MathML text integration point or HTML integration point.
                    loop {
                        let cur = self.current_node();
                        if cur.as_element().unwrap().name.ns == NS_HTML
                            || is_mathml_text_integration_point(&cur)
                            || is_html_integration_point(&cur)
                        {
                            break;
                        }
                        self.pop();
                    }
                    let mode = self.mode;
                    self.process(Token::StartTag(tag), mode);
                    return;
                }
                let acn = self.adjusted_current_node().unwrap();
                let ns = acn.as_element().unwrap().name.ns.clone();
                let self_closing = tag.self_closing;
                let is_script = tag.name == "script";
                self.insert_element(&tag, &ns);
                if self_closing {
                    if is_script && ns == NS_SVG {
                        self.pop();
                    } else {
                        self.pop();
                    }
                }
            }
            Token::EndTag(tag) => {
                let name = tag.name.as_str();
                let mut i = self.open.len() - 1;
                let node = self.open[i].clone();
                let node_local = node.as_element().unwrap().name.local.to_ascii_lowercase();
                if node_local != name {
                    // parse error
                }
                loop {
                    if i == 0 {
                        // node is the first node in the stack: return
                        return;
                    }
                    let node = self.open[i].clone();
                    let e = node.as_element().unwrap();
                    if e.name.local.to_ascii_lowercase() == name {
                        while self.open.len() > i {
                            self.pop();
                        }
                        return;
                    }
                    i -= 1;
                    let next = self.open[i].clone();
                    if next.as_element().unwrap().name.ns == NS_HTML {
                        // Process the token according to the rules for the current insertion mode.
                        let mode = self.mode;
                        self.process(Token::EndTag(tag), mode);
                        return;
                    }
                }
            }
            Token::Eof => {
                let mode = self.mode;
                self.process(Token::Eof, mode);
            }
        }
    }
}
