// Insertion mode handlers for the tree builder (included from treebuilder.rs).

impl TreeBuilder {
    fn step(&mut self, token: Token, mode: Mode) -> Step {
        match mode {
            Mode::Initial => self.mode_initial(token),
            Mode::BeforeHtml => self.mode_before_html(token),
            Mode::BeforeHead => self.mode_before_head(token),
            Mode::InHead => self.mode_in_head(token),
            Mode::InHeadNoscript => self.mode_in_head_noscript(token),
            Mode::AfterHead => self.mode_after_head(token),
            Mode::InBody => self.mode_in_body(token),
            Mode::Text => self.mode_text(token),
            Mode::InTable => self.mode_in_table(token),
            Mode::InTableText => self.mode_in_table_text(token),
            Mode::InCaption => self.mode_in_caption(token),
            Mode::InColumnGroup => self.mode_in_column_group(token),
            Mode::InTableBody => self.mode_in_table_body(token),
            Mode::InRow => self.mode_in_row(token),
            Mode::InCell => self.mode_in_cell(token),
            Mode::InSelect => self.mode_in_select(token),
            Mode::InSelectInTable => self.mode_in_select_in_table(token),
            Mode::InTemplate => self.mode_in_template(token),
            Mode::AfterBody => self.mode_after_body(token),
            Mode::InFrameset => self.mode_in_frameset(token),
            Mode::AfterFrameset => self.mode_after_frameset(token),
            Mode::AfterAfterBody => self.mode_after_after_body(token),
            Mode::AfterAfterFrameset => self.mode_after_after_frameset(token),
        }
    }

    // ---- 13.2.6.4.1 initial ----
    fn mode_initial(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => Step::Done,
            Token::Comment(c) => {
                self.insert_comment_in(&self.document.clone(), c);
                Step::Done
            }
            Token::Doctype { name, public_id, system_id, force_quirks } => {
                let q = doctype_quirks(&name, &public_id, &system_id, force_quirks);
                let node = NodeRef::new_doctype(
                    name.unwrap_or_default(),
                    public_id.unwrap_or_default(),
                    system_id.unwrap_or_default(),
                );
                self.document.append(node);
                self.set_quirks(q);
                self.mode = Mode::BeforeHtml;
                Step::Done
            }
            t => {
                self.set_quirks(QuirksMode::Quirks);
                self.mode = Mode::BeforeHtml;
                Step::Reprocess(t)
            }
        }
    }

    // ---- before html ----
    fn mode_before_html(&mut self, token: Token) -> Step {
        match token {
            Token::Doctype { .. } => Step::Done,
            Token::Comment(c) => {
                self.insert_comment_in(&self.document.clone(), c);
                Step::Done
            }
            Token::Characters(ref s) if is_ws_str(s) => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => {
                let node = self.create_element(tag, NS_HTML);
                self.document.append(node.clone());
                self.open.push(node);
                self.mode = Mode::BeforeHead;
                Step::Done
            }
            Token::EndTag(ref tag) if !matches!(tag.name.as_str(), "head" | "body" | "html" | "br") => Step::Done,
            t => {
                let tag = Tag { name: "html".to_string(), attrs: Vec::new(), self_closing: false };
                let node = self.create_element(&tag, NS_HTML);
                self.document.append(node.clone());
                self.open.push(node);
                self.mode = Mode::BeforeHead;
                Step::Reprocess(t)
            }
        }
    }

    // ---- before head ----
    fn mode_before_head(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => Step::Done,
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::StartTag(ref tag) if tag.name == "head" => {
                let node = self.insert_html_element(tag);
                self.head = Some(node);
                self.mode = Mode::InHead;
                Step::Done
            }
            Token::EndTag(ref tag) if !matches!(tag.name.as_str(), "head" | "body" | "html" | "br") => Step::Done,
            t => {
                let node = self.insert_html_element_named("head");
                self.head = Some(node);
                self.mode = Mode::InHead;
                Step::Reprocess(t)
            }
        }
    }

    // ---- in head ----
    fn mode_in_head(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => {
                self.insert_text(s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "html" => self.mode_in_body(token),
                "base" | "basefont" | "bgsound" | "link" | "meta" => {
                    self.insert_html_element(tag);
                    self.pop();
                    Step::Done
                }
                "title" => {
                    self.generic_rcdata(tag);
                    Step::Done
                }
                "noscript" if self.scripting => {
                    self.generic_rawtext(tag);
                    Step::Done
                }
                "noframes" | "style" => {
                    self.generic_rawtext(tag);
                    Step::Done
                }
                "noscript" => {
                    self.insert_html_element(tag);
                    self.mode = Mode::InHeadNoscript;
                    Step::Done
                }
                "script" => {
                    let loc = self.appropriate_insertion_location(None);
                    let node = self.create_element(tag, NS_HTML);
                    Self::insert_at(loc, node.clone());
                    self.open.push(node);
                    self.raw_request = Some(RawKind::ScriptData);
                    self.original_mode = self.mode;
                    self.mode = Mode::Text;
                    Step::Done
                }
                "template" => {
                    self.insert_html_element(tag);
                    self.formatting.push(FormatEntry::Marker);
                    self.frameset_ok = false;
                    self.mode = Mode::InTemplate;
                    self.template_modes.push(Mode::InTemplate);
                    Step::Done
                }
                "head" => Step::Done,
                _ => self.in_head_anything_else(token),
            },
            Token::EndTag(ref tag) => match tag.name.as_str() {
                "head" => {
                    self.pop();
                    self.mode = Mode::AfterHead;
                    Step::Done
                }
                "body" | "html" | "br" => self.in_head_anything_else(token),
                "template" => {
                    if !self.open_has_template() {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags_thoroughly();
                    self.pop_until_html("template");
                    self.clear_formatting_to_marker();
                    self.template_modes.pop();
                    self.reset_insertion_mode();
                    Step::Done
                }
                _ => Step::Done,
            },
            t => self.in_head_anything_else(t),
        }
    }

    fn in_head_anything_else(&mut self, token: Token) -> Step {
        self.pop();
        self.mode = Mode::AfterHead;
        Step::Reprocess(token)
    }

    fn generic_rcdata(&mut self, tag: &Tag) {
        self.insert_html_element(tag);
        self.raw_request = Some(RawKind::Rcdata);
        self.original_mode = self.mode;
        self.mode = Mode::Text;
    }

    fn generic_rawtext(&mut self, tag: &Tag) {
        self.insert_html_element(tag);
        self.raw_request = Some(RawKind::Rawtext);
        self.original_mode = self.mode;
        self.mode = Mode::Text;
    }

    // ---- in head noscript ----
    fn mode_in_head_noscript(&mut self, token: Token) -> Step {
        match token {
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) if tag.name == "html" => self.mode_in_body(token),
            Token::EndTag(ref tag) if tag.name == "noscript" => {
                self.pop();
                self.mode = Mode::InHead;
                Step::Done
            }
            Token::Characters(ref s) if is_ws_str(s) => self.mode_in_head(token),
            Token::Comment(_) => self.mode_in_head(token),
            Token::StartTag(ref tag)
                if matches!(tag.name.as_str(), "basefont" | "bgsound" | "link" | "meta" | "noframes" | "style") =>
            {
                self.mode_in_head(token)
            }
            Token::EndTag(ref tag) if tag.name == "br" => {
                self.pop();
                self.mode = Mode::InHead;
                Step::Reprocess(token)
            }
            Token::StartTag(ref tag) if matches!(tag.name.as_str(), "head" | "noscript") => Step::Done,
            Token::EndTag(_) => Step::Done,
            t => {
                self.pop();
                self.mode = Mode::InHead;
                Step::Reprocess(t)
            }
        }
    }

    // ---- after head ----
    fn mode_after_head(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(ref s) if is_ws_str(s) => {
                self.insert_text(s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "html" => self.mode_in_body(token),
                "body" => {
                    self.insert_html_element(tag);
                    self.frameset_ok = false;
                    self.mode = Mode::InBody;
                    Step::Done
                }
                "frameset" => {
                    self.insert_html_element(tag);
                    self.mode = Mode::InFrameset;
                    Step::Done
                }
                "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
                | "title" => {
                    let head = self.head.clone().expect("head");
                    self.open.push(head.clone());
                    let r = self.mode_in_head(token);
                    // Remove the head element from the stack.
                    if let Some(pos) = self.open.iter().rposition(|n| *n == head) {
                        self.open.remove(pos);
                    }
                    r
                }
                "head" => Step::Done,
                _ => self.after_head_anything_else(token),
            },
            Token::EndTag(ref tag) => match tag.name.as_str() {
                "template" => self.mode_in_head(token),
                "body" | "html" | "br" => self.after_head_anything_else(token),
                _ => Step::Done,
            },
            t => self.after_head_anything_else(t),
        }
    }

    fn after_head_anything_else(&mut self, token: Token) -> Step {
        self.insert_html_element_named("body");
        self.mode = Mode::InBody;
        Step::Reprocess(token)
    }

    // ---- in body ----
    fn mode_in_body(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    return Step::Done;
                }
                self.reconstruct_formatting();
                if !is_ws_str(&s) {
                    self.frameset_ok = false;
                }
                self.insert_text(&s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::Eof => {
                if !self.template_modes.is_empty() {
                    return self.mode_in_template(Token::Eof);
                }
                Step::Done
            }
            Token::StartTag(tag) => self.in_body_start_tag(tag),
            Token::EndTag(tag) => self.in_body_end_tag(tag),
        }
    }

    fn in_body_start_tag(&mut self, tag: Tag) -> Step {
        match tag.name.as_str() {
            "html" => {
                if self.open_has_template() {
                    return Step::Done;
                }
                let top = self.open[0].clone();
                let e = top.as_element().unwrap();
                let mut attrs = e.attributes.borrow_mut();
                for (k, v) in &tag.attrs {
                    if !attrs.contains(k) {
                        attrs.insert(k, v.clone());
                    }
                }
                Step::Done
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template"
            | "title" => self.mode_in_head(Token::StartTag(tag)),
            "body" => {
                if self.open.len() < 2 || !is_html(&self.open[1], "body") || self.open_has_template() {
                    return Step::Done;
                }
                self.frameset_ok = false;
                let body = self.open[1].clone();
                let e = body.as_element().unwrap();
                let mut attrs = e.attributes.borrow_mut();
                for (k, v) in &tag.attrs {
                    if !attrs.contains(k) {
                        attrs.insert(k, v.clone());
                    }
                }
                Step::Done
            }
            "frameset" => {
                if self.open.len() < 2 || !is_html(&self.open[1], "body") {
                    return Step::Done;
                }
                if !self.frameset_ok {
                    return Step::Done;
                }
                let body = self.open[1].clone();
                body.detach();
                while self.open.len() > 1 {
                    self.pop();
                }
                self.insert_html_element(&tag);
                self.mode = Mode::InFrameset;
                Step::Done
            }
            "address" | "article" | "aside" | "blockquote" | "center" | "details" | "dialog" | "dir" | "div" | "dl"
            | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "main" | "menu" | "nav" | "ol"
            | "p" | "section" | "summary" | "ul" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                if is_html_in(&self.current_node(), HEADINGS) {
                    self.pop();
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "pre" | "listing" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                self.ignore_lf = true;
                self.frameset_ok = false;
                Step::Done
            }
            "form" => {
                if self.form.is_some() && !self.open_has_template() {
                    return Step::Done;
                }
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                let node = self.insert_html_element(&tag);
                if !self.open_has_template() {
                    self.form = Some(node);
                }
                Step::Done
            }
            "li" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                loop {
                    i -= 1;
                    let node = self.open[i].clone();
                    if is_html(&node, "li") {
                        self.generate_implied_end_tags(Some("li"));
                        self.pop_until_html("li");
                        break;
                    }
                    if is_special(&node) && !is_html_in(&node, &["address", "div", "p"]) {
                        break;
                    }
                    if i == 0 {
                        break;
                    }
                }
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "dd" | "dt" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                loop {
                    i -= 1;
                    let node = self.open[i].clone();
                    if is_html(&node, "dd") {
                        self.generate_implied_end_tags(Some("dd"));
                        self.pop_until_html("dd");
                        break;
                    }
                    if is_html(&node, "dt") {
                        self.generate_implied_end_tags(Some("dt"));
                        self.pop_until_html("dt");
                        break;
                    }
                    if is_special(&node) && !is_html_in(&node, &["address", "div", "p"]) {
                        break;
                    }
                    if i == 0 {
                        break;
                    }
                }
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "plaintext" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                self.raw_request = Some(RawKind::Plaintext);
                Step::Done
            }
            "button" => {
                if self.has_in_scope("button", Scope::Default) {
                    self.generate_implied_end_tags(None);
                    self.pop_until_html("button");
                }
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                self.frameset_ok = false;
                Step::Done
            }
            "a" => {
                if let Some((idx, node)) = self.find_formatting("a") {
                    self.adoption_agency("a");
                    // Remove from formatting list and stack if still there.
                    if let Some(i) = self.formatting_index_of(&node) {
                        self.formatting.remove(i);
                    } else {
                        let _ = idx;
                    }
                    if let Some(pos) = self.open.iter().position(|n| *n == node) {
                        self.open.remove(pos);
                    }
                }
                self.reconstruct_formatting();
                let node = self.insert_html_element(&tag);
                self.push_formatting(node, tag);
                Step::Done
            }
            "b" | "big" | "code" | "em" | "font" | "i" | "s" | "small" | "strike" | "strong" | "tt" | "u" => {
                self.reconstruct_formatting();
                let node = self.insert_html_element(&tag);
                self.push_formatting(node, tag);
                Step::Done
            }
            "nobr" => {
                self.reconstruct_formatting();
                if self.has_in_scope("nobr", Scope::Default) {
                    self.adoption_agency("nobr");
                    self.reconstruct_formatting();
                }
                let node = self.insert_html_element(&tag);
                self.push_formatting(node, tag);
                Step::Done
            }
            "applet" | "marquee" | "object" => {
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                self.formatting.push(FormatEntry::Marker);
                self.frameset_ok = false;
                Step::Done
            }
            "table" => {
                if self.quirks != QuirksMode::Quirks && self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                self.frameset_ok = false;
                self.mode = Mode::InTable;
                Step::Done
            }
            "area" | "br" | "embed" | "img" | "keygen" | "wbr" => {
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                self.pop();
                self.frameset_ok = false;
                Step::Done
            }
            "input" => {
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                self.pop();
                let hidden = tag
                    .attrs
                    .iter()
                    .find(|(k, _)| k == "type")
                    .map_or(false, |(_, v)| v.eq_ignore_ascii_case("hidden"));
                if !hidden {
                    self.frameset_ok = false;
                }
                Step::Done
            }
            "param" | "source" | "track" => {
                self.insert_html_element(&tag);
                self.pop();
                Step::Done
            }
            "hr" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.insert_html_element(&tag);
                self.pop();
                self.frameset_ok = false;
                Step::Done
            }
            "image" => {
                let mut t = tag;
                t.name = "img".to_string();
                self.in_body_start_tag(t)
            }
            "textarea" => {
                self.insert_html_element(&tag);
                self.ignore_lf = true;
                self.raw_request = Some(RawKind::Rcdata);
                self.original_mode = self.mode;
                self.frameset_ok = false;
                self.mode = Mode::Text;
                Step::Done
            }
            "xmp" => {
                if self.has_in_scope("p", Scope::Button) {
                    self.close_p_element();
                }
                self.reconstruct_formatting();
                self.frameset_ok = false;
                self.generic_rawtext(&tag);
                Step::Done
            }
            "iframe" => {
                self.frameset_ok = false;
                self.generic_rawtext(&tag);
                Step::Done
            }
            "noembed" => {
                self.generic_rawtext(&tag);
                Step::Done
            }
            "noscript" if self.scripting => {
                self.generic_rawtext(&tag);
                Step::Done
            }
            "select" => {
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                self.frameset_ok = false;
                if matches!(
                    self.mode,
                    Mode::InTable | Mode::InCaption | Mode::InTableBody | Mode::InRow | Mode::InCell
                ) {
                    self.mode = Mode::InSelectInTable;
                } else {
                    self.mode = Mode::InSelect;
                }
                Step::Done
            }
            "optgroup" | "option" => {
                if is_html(&self.current_node(), "option") {
                    self.pop();
                }
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                Step::Done
            }
            "rb" | "rtc" => {
                if self.has_in_scope("ruby", Scope::Default) {
                    self.generate_implied_end_tags(None);
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "rp" | "rt" => {
                if self.has_in_scope("ruby", Scope::Default) {
                    self.generate_implied_end_tags(Some("rtc"));
                }
                self.insert_html_element(&tag);
                Step::Done
            }
            "math" => {
                self.reconstruct_formatting();
                let self_closing = tag.self_closing;
                self.insert_element(&tag, NS_MATHML);
                if self_closing {
                    self.pop();
                }
                Step::Done
            }
            "svg" => {
                self.reconstruct_formatting();
                let self_closing = tag.self_closing;
                self.insert_element(&tag, NS_SVG);
                if self_closing {
                    self.pop();
                }
                Step::Done
            }
            "caption" | "col" | "colgroup" | "frame" | "head" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                Step::Done
            }
            _ => {
                self.reconstruct_formatting();
                self.insert_html_element(&tag);
                Step::Done
            }
        }
    }

    fn close_p_element(&mut self) {
        self.generate_implied_end_tags(Some("p"));
        self.pop_until_html("p");
    }

    fn in_body_end_tag(&mut self, tag: Tag) -> Step {
        match tag.name.as_str() {
            "template" => self.mode_in_head(Token::EndTag(tag)),
            "body" => {
                if !self.has_in_scope("body", Scope::Default) {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Done
            }
            "html" => {
                if !self.has_in_scope("body", Scope::Default) {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Reprocess(Token::EndTag(tag))
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details" | "dialog" | "dir"
            | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "listing"
            | "main" | "menu" | "nav" | "ol" | "pre" | "section" | "summary" | "ul" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html(&tag.name);
                Step::Done
            }
            "form" => {
                if !self.open_has_template() {
                    let node = self.form.take();
                    let node = match node {
                        Some(n) => n,
                        None => return Step::Done,
                    };
                    if !self.has_node_in_scope(&node, Scope::Default) {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags(None);
                    if let Some(pos) = self.open.iter().position(|n| *n == node) {
                        self.open.remove(pos);
                    }
                } else {
                    if !self.has_in_scope("form", Scope::Default) {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags(None);
                    self.pop_until_html("form");
                }
                Step::Done
            }
            "p" => {
                if !self.has_in_scope("p", Scope::Button) {
                    self.insert_html_element_named("p");
                }
                self.close_p_element();
                Step::Done
            }
            "li" => {
                if !self.has_in_scope("li", Scope::ListItem) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some("li"));
                self.pop_until_html("li");
                Step::Done
            }
            "dd" | "dt" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some(&tag.name));
                self.pop_until_html(&tag.name);
                Step::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if !self.has_any_in_scope(HEADINGS, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html_in(HEADINGS);
                Step::Done
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small" | "strike" | "strong" | "tt"
            | "u" => {
                self.adoption_agency(&tag.name);
                Step::Done
            }
            "applet" | "marquee" | "object" => {
                if !self.has_in_scope(&tag.name, Scope::Default) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_html(&tag.name);
                self.clear_formatting_to_marker();
                Step::Done
            }
            "br" => {
                let t = Tag { name: "br".to_string(), attrs: Vec::new(), self_closing: false };
                self.in_body_start_tag(t)
            }
            _ => {
                self.any_other_end_tag(&tag.name);
                Step::Done
            }
        }
    }

    fn any_other_end_tag(&mut self, name: &str) {
        let mut i = self.open.len();
        loop {
            if i == 0 {
                return;
            }
            i -= 1;
            let node = self.open[i].clone();
            if is_html(&node, name) {
                self.generate_implied_end_tags(Some(name));
                // Pop until node popped.
                while self.open.len() > i {
                    self.pop();
                }
                return;
            }
            if is_special(&node) {
                return;
            }
        }
    }

    /// The adoption agency algorithm.
    fn adoption_agency(&mut self, subject: &str) {
        // Step 1.
        let cur = self.current_node();
        if is_html(&cur, subject) && self.formatting_index_of(&cur).is_none() {
            self.pop();
            return;
        }
        let mut outer = 0;
        while outer < 8 {
            outer += 1;
            // Step 4.3: formatting element.
            let (fmt_idx, fmt_elem) = match self.find_formatting(subject) {
                Some(x) => x,
                None => {
                    self.any_other_end_tag(subject);
                    return;
                }
            };
            // 4.4: if not in stack of open elements.
            let stack_pos = match self.open.iter().position(|n| *n == fmt_elem) {
                Some(p) => p,
                None => {
                    self.formatting.remove(fmt_idx);
                    return;
                }
            };
            // 4.5: in stack but not in scope.
            if !self.has_node_in_scope(&fmt_elem, Scope::Default) {
                return;
            }
            // 4.6: parse error if not current node (ignored).
            // 4.7: furthest block.
            let mut furthest_block: Option<(usize, NodeRef)> = None;
            for i in (stack_pos + 1)..self.open.len() {
                if is_special(&self.open[i]) {
                    furthest_block = Some((i, self.open[i].clone()));
                    break;
                }
            }
            // 4.8.
            let (fb_pos, furthest_block) = match furthest_block {
                Some(x) => x,
                None => {
                    while self.open.len() > stack_pos {
                        self.pop();
                    }
                    self.formatting.remove(fmt_idx);
                    return;
                }
            };
            // 4.9: common ancestor.
            let common_ancestor = self.open[stack_pos - 1].clone();
            // 4.10: bookmark.
            let mut bookmark = fmt_idx;
            // 4.11.
            let mut node_pos = fb_pos;
            let mut node = furthest_block.clone();
            let mut last_node = furthest_block.clone();
            let mut inner = 0;
            loop {
                inner += 1;
                // 4.13.3: node = element immediately above node in the stack
                node_pos -= 1;
                node = self.open[node_pos].clone();
                // 4.13.4
                if node == fmt_elem {
                    break;
                }
                // 4.13.5
                let node_fmt_idx = self.formatting_index_of(&node);
                if inner > 3 {
                    if let Some(fi) = node_fmt_idx {
                        self.formatting.remove(fi);
                        if fi < bookmark {
                            bookmark -= 1;
                        }
                    }
                    self.open.remove(node_pos);
                    continue;
                }
                // 4.13.6
                let node_fmt_idx = match node_fmt_idx {
                    Some(fi) => fi,
                    None => {
                        self.open.remove(node_pos);
                        continue;
                    }
                };
                // 4.13.7: create element for the token for which node was created.
                let tag = match &self.formatting[node_fmt_idx] {
                    FormatEntry::Element(_, t) => t.clone(),
                    _ => unreachable!(),
                };
                let new_elem = self.create_element(&tag, NS_HTML);
                self.formatting[node_fmt_idx] = FormatEntry::Element(new_elem.clone(), tag);
                self.open[node_pos] = new_elem.clone();
                node = new_elem;
                // 4.13.8
                if last_node == furthest_block {
                    bookmark = node_fmt_idx + 1;
                }
                // 4.13.9
                node.append(last_node.clone());
                // 4.13.10
                last_node = node.clone();
            }
            let _ = node;
            // 4.14: insert last_node at appropriate place for inserting a node with common_ancestor as override.
            let loc = self.appropriate_insertion_location(Some(common_ancestor.clone()));
            Self::insert_at(loc, last_node.clone());
            // 4.15
            let tag = match &self.formatting[fmt_idx] {
                FormatEntry::Element(_, t) => t.clone(),
                _ => unreachable!(),
            };
            let new_elem = self.create_element(&tag, NS_HTML);
            // 4.16: move all children of furthest block to new_elem.
            let mut children: Vec<NodeRef> = furthest_block.children().collect();
            for c in children.drain(..) {
                new_elem.append(c);
            }
            // 4.17
            furthest_block.append(new_elem.clone());
            // 4.18: remove fmt_elem from formatting list, insert new_elem at bookmark.
            // Recompute fmt_idx (may have shifted).
            let cur_fmt_idx = self.formatting_index_of(&fmt_elem).unwrap();
            self.formatting.remove(cur_fmt_idx);
            if cur_fmt_idx < bookmark {
                bookmark -= 1;
            }
            if bookmark > self.formatting.len() {
                bookmark = self.formatting.len();
            }
            self.formatting.insert(bookmark, FormatEntry::Element(new_elem.clone(), tag));
            // 4.19: remove fmt_elem from stack; insert new_elem immediately below furthest block.
            let fpos = self.open.iter().position(|n| *n == fmt_elem).unwrap();
            self.open.remove(fpos);
            let fbpos = self.open.iter().position(|n| *n == furthest_block).unwrap();
            self.open.insert(fbpos + 1, new_elem);
        }
    }

    // ---- text ----
    fn mode_text(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                self.insert_text(&s);
                Step::Done
            }
            Token::Eof => {
                self.pop();
                self.mode = self.original_mode;
                Step::Reprocess(Token::Eof)
            }
            Token::EndTag(_) => {
                self.pop();
                self.mode = self.original_mode;
                Step::Done
            }
            _ => Step::Done,
        }
    }

    // ---- in table ----
    fn mode_in_table(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(_)
                if is_html_in(&self.current_node(), &["table", "tbody", "tfoot", "thead", "tr"]) =>
            {
                self.pending_table_text.clear();
                self.original_mode = self.mode;
                self.mode = Mode::InTableText;
                Step::Reprocess(token)
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Step::Done
            }
            Token::Doctype { .. } => Step::Done,
            Token::StartTag(ref tag) => match tag.name.as_str() {
                "caption" => {
                    self.clear_stack_back_to_table_context();
                    self.formatting.push(FormatEntry::Marker);
                    self.insert_html_element(tag);
                    self.mode = Mode::InCaption;
                    Step::Done
                }
                "colgroup" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element(tag);
                    self.mode = Mode::InColumnGroup;
                    Step::Done
                }
                "col" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element_named("colgroup");
                    self.mode = Mode::InColumnGroup;
                    Step::Reprocess(token)
                }
                "tbody" | "tfoot" | "thead" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element(tag);
                    self.mode = Mode::InTableBody;
                    Step::Done
                }
                "td" | "th" | "tr" => {
                    self.clear_stack_back_to_table_context();
                    self.insert_html_element_named("tbody");
                    self.mode = Mode::InTableBody;
                    Step::Reprocess(token)
                }
                "table" => {
                    if !self.has_in_scope("table", Scope::Table) {
                        return Step::Done;
                    }
                    self.pop_until_html("table");
                    self.reset_insertion_mode();
                    Step::Reprocess(token)
                }
                "style" | "script" | "template" => self.mode_in_head(token),
                "input" => {
                    let hidden = tag
                        .attrs
                        .iter()
                        .find(|(k, _)| k == "type")
                        .map_or(false, |(_, v)| v.eq_ignore_ascii_case("hidden"));
                    if !hidden {
                        return self.in_table_anything_else(token);
                    }
                    self.insert_html_element(tag);
                    self.pop();
                    Step::Done
                }
                "form" => {
                    if self.open_has_template() || self.form.is_some() {
                        return Step::Done;
                    }
                    let node = self.insert_html_element(tag);
                    self.form = Some(node);
                    self.pop();
                    Step::Done
                }
                _ => self.in_table_anything_else(token),
            },
            Token::EndTag(ref tag) => match tag.name.as_str() {
                "table" => {
                    if !self.has_in_scope("table", Scope::Table) {
                        return Step::Done;
                    }
                    self.pop_until_html("table");
                    self.reset_insertion_mode();
                    Step::Done
                }
                "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead"
                | "tr" => Step::Done,
                "template" => self.mode_in_head(token),
                _ => self.in_table_anything_else(token),
            },
            Token::Eof => self.mode_in_body(token),
            Token::Characters(_) => self.in_table_anything_else(token),
        }
    }

    fn in_table_anything_else(&mut self, token: Token) -> Step {
        self.foster_parenting = true;
        let r = self.mode_in_body(token);
        self.foster_parenting = false;
        // Any reprocess requested by in-body rules must happen without foster parenting
        // (the spec re-dispatches in the new mode anyway).
        r
    }

    // ---- in table text ----
    fn mode_in_table_text(&mut self, token: Token) -> Step {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    return Step::Done;
                }
                self.pending_table_text.push(s);
                Step::Done
            }
            t => {
                let pending = std::mem::take(&mut self.pending_table_text);
                if pending.iter().any(|s| !is_ws_str(s)) {
                    for s in pending {
                        self.foster_parenting = true;
                        let _ = self.mode_in_body(Token::Characters(s));
                        self.foster_parenting = false;
                    }
                } else {
                    for s in pending {
                        self.insert_text(&s);
                    }
                }
                self.mode = self.original_mode;
