    // ---- foreign content ----
    fn process_foreign(&mut self, token: Token) {
        match token {
            Token::Characters(s) => {
                if s == "\0" {
                    self.insert_text("\u{FFFD}");
                } else {
                    if !is_ws_str(&s) {
