                        }
                        self.pop();
                    }
                    let mode = self.mode;
                    self.process(Token::StartTag(tag), mode);
                    return;
                }
                let acn = self.adjusted_current_node().unwrap();
                let ns = acn.as_element().unwrap().name.ns.clone();
                let self_closing = tag.self_closing;
                let is_script = tag.name == "script";
                self.insert_element(&tag, &ns);
                if self_closing {
                    if is_script && ns == NS_SVG {
                        self.pop();
                    } else {
                        self.pop();
                    }
                }
            }
            Token::EndTag(tag) => {
                let name = tag.name.as_str();
                let mut i = self.open.len() - 1;
                let node = self.open[i].clone();
                let node_local = node.as_element().unwrap().name.local.to_ascii_lowercase();
                if node_local != name {
                    // parse error
                }
                loop {
                    if i == 0 {
                        // node is the first node in the stack: return
                        return;
                    }
                    let node = self.open[i].clone();
                    let e = node.as_element().unwrap();
                    if e.name.local.to_ascii_lowercase() == name {
                        while self.open.len() > i {
                            self.pop();
                        }
                        return;
                    }
                    i -= 1;
                    let next = self.open[i].clone();
                    if next.as_element().unwrap().name.ns == NS_HTML {
                        // Process the token according to the rules for the current insertion mode.
                        let mode = self.mode;
                        self.process(Token::EndTag(tag), mode);
                        return;
                    }
                }
            }
            Token::Eof => {
                let mode = self.mode;
                self.process(Token::Eof, mode);
            }
        }
    }
