//! HTML serialisation (plain and "pretty").

use crate::dom::*;

struct ElemInfo {
    html_name: Option<String>,
    ignore_children: bool,
}

/// Low-level serializer writing into a String.
pub struct HtmlSerializer {
    pub out: String,
    stack: Vec<ElemInfo>,
}

fn escape(out: &mut String, text: &str, attr_mode: bool) {
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{00A0}' => out.push_str("&nbsp;"),
            '"' if attr_mode => out.push_str("&quot;"),
            '<' if !attr_mode => out.push_str("&lt;"),
            '>' if !attr_mode => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn is_void(name: &QualName) -> bool {
    name.ns == NS_HTML
        && matches!(
            name.local.as_str(),
            "area"
                | "base"
                | "basefont"
                | "bgsound"
                | "br"
                | "col"
                | "embed"
                | "frame"
                | "hr"
                | "img"
                | "input"
                | "keygen"
                | "link"
                | "meta"
                | "param"
                | "source"
                | "track"
                | "wbr"
        )
}

impl HtmlSerializer {
    pub fn new() -> HtmlSerializer {
        HtmlSerializer {
            out: String::new(),
            stack: vec![ElemInfo { html_name: None, ignore_children: false }],
        }
    }

    fn parent(&self) -> &ElemInfo {
        self.stack.last().expect("no parent ElemInfo")
    }

    pub fn start_elem(&mut self, name: &QualName, attrs: &Attributes) {
        let html_name = if name.ns == NS_HTML { Some(name.local.clone()) } else { None };
        if self.parent().ignore_children {
            self.stack.push(ElemInfo { html_name, ignore_children: true });
            return;
        }
        self.out.push('<');
        self.out.push_str(&name.local);
        for (key, attr) in &attrs.map {
            self.out.push(' ');
            match key.ns.as_str() {
                "" => {}
                NS_XML => self.out.push_str("xml:"),
                NS_XMLNS => {
                    if key.local != "xmlns" {
                        self.out.push_str("xmlns:");
                    }
                }
                NS_XLINK => self.out.push_str("xlink:"),
                _ => self.out.push_str("unknown_namespace:"),
            }
            self.out.push_str(&key.local);
            self.out.push_str("=\"");
            escape(&mut self.out, &attr.value, true);
            self.out.push('"');
        }
        self.out.push('>');
        let ignore_children = is_void(name);
        self.stack.push(ElemInfo { html_name, ignore_children });
    }

    pub fn end_elem(&mut self, name: &QualName) {
        let info = self.stack.pop().expect("no ElemInfo");
