//! CSS tokenizer (css-syntax-3 flavoured, mirroring the behaviour of the
//! `cssparser` family of tokenizers closely enough for selector parsing).

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IDHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number { has_sign: bool, value: f64, int_value: Option<i32> },
    Percentage { has_sign: bool, unit_value: f64, int_value: Option<i32> },
    Dimension { has_sign: bool, value: f64, int_value: Option<i32>, unit: String },
    WhiteSpace,
    Comment,
    Colon,
    Semicolon,
    Comma,
    IncludeMatch,
    DashMatch,
    PrefixMatch,
    SuffixMatch,
    SubstringMatch,
    CDO,
    CDC,
    Function(String),
    ParenthesisBlock,
    SquareBracketBlock,
    CurlyBracketBlock,
    BadUrl,
    BadString,
    CloseParenthesis,
    CloseSquareBracket,
    CloseCurlyBracket,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BlockType {
    Parenthesis,
    SquareBracket,
    CurlyBracket,
}

impl Token {
    pub fn opening_block(&self) -> Option<BlockType> {
        match self {
            Token::Function(_) | Token::ParenthesisBlock => Some(BlockType::Parenthesis),
            Token::SquareBracketBlock => Some(BlockType::SquareBracket),
            Token::CurlyBracketBlock => Some(BlockType::CurlyBracket),
            _ => None,
        }
    }
    pub fn closing_block(&self) -> Option<BlockType> {
        match self {
            Token::CloseParenthesis => Some(BlockType::Parenthesis),
            Token::CloseSquareBracket => Some(BlockType::SquareBracket),
            Token::CloseCurlyBracket => Some(BlockType::CurlyBracket),
            _ => None,
        }
    }
}

struct Tokenizer<'a> {
    input: &'a [u8],
    pos: usize,
    src: &'a str,
}

fn is_ws_byte(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | b'\r' | b'\x0C')
}

fn is_newline(b: u8) -> bool {
    matches!(b, b'\n' | b'\r' | b'\x0C')
}

fn is_name_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_' || b == 0 || !b.is_ascii()
}

fn is_name_char(b: u8) -> bool {
    is_name_start(b) || b.is_ascii_digit() || b == b'-'
}

impl<'a> Tokenizer<'a> {
    fn eof(&self) -> bool {
        self.pos >= self.input.len()
    }
    fn byte_at(&self, off: usize) -> Option<u8> {
        self.input.get(self.pos + off).copied()
    }
    fn has_newline_at(&self, off: usize) -> bool {
        self.byte_at(off).map_or(false, is_newline)
    }
    fn starts_with(&self, s: &[u8]) -> bool {
        self.input[self.pos..].starts_with(s)
    }

    /// "Would start an identifier" check at the current position.
    fn is_ident_start(&self) -> bool {
        match self.byte_at(0) {
            None => false,
            Some(b) => match b {
                b'a'..=b'z' | b'A'..=b'Z' | b'_' | 0 => true,
                b'-' => match self.byte_at(1) {
                    Some(b2) => match b2 {
                        b'a'..=b'z' | b'A'..=b'Z' | b'-' | b'_' | 0 => true,
                        b'\\' => !self.has_newline_at(2),
                        b => !b.is_ascii(),
                    },
                    None => false,
                },
                b'\\' => !self.has_newline_at(1),
                b => !b.is_ascii(),
            },
        }
    }

    fn next_char(&mut self) -> char {
        let s = &self.src[self.pos..];
        let c = s.chars().next().unwrap();
        self.pos += c.len_utf8();
        c
    }

    fn consume_escape(&mut self) -> char {
        // Assumes the backslash has been consumed and the escape is valid.
        match self.byte_at(0) {
            None => '\u{FFFD}',
            Some(b) if b.is_ascii_hexdigit() => {
                let mut value: u32 = 0;
                let mut digits = 0;
                while digits < 6 {
                    match self.byte_at(0) {
                        Some(h) if h.is_ascii_hexdigit() => {
                            value = value * 16 + (h as char).to_digit(16).unwrap();
                            self.pos += 1;
                            digits += 1;
                        }
                        _ => break,
                    }
                }
                // Optional single whitespace.
                match self.byte_at(0) {
                    Some(b'\r') => {
                        self.pos += 1;
                        if self.byte_at(0) == Some(b'\n') {
                            self.pos += 1;
                        }
                    }
                    Some(w) if is_ws_byte(w) => self.pos += 1,
                    _ => {}
                }
                if value == 0 || (0xD800..=0xDFFF).contains(&value) || value > 0x10FFFF {
                    '\u{FFFD}'
                } else {
                    char::from_u32(value).unwrap_or('\u{FFFD}')
                }
            }
            Some(0) => {
                self.pos += 1;
                '\u{FFFD}'
            }
            Some(_) => self.next_char(),
        }
    }

    fn consume_name(&mut self) -> String {
        let mut out = String::new();
        loop {
            match self.byte_at(0) {
                None => break,
                Some(b) => {
                    if b == b'\\' {
                        if self.has_newline_at(1) {
                            break;
                        }
                        self.pos += 1;
                        let c = self.consume_escape();
                        out.push(c);
                    } else if b == 0 {
                        self.pos += 1;
                        out.push('\u{FFFD}');
                    } else if is_name_char(b) {
                        let c = self.next_char();
                        out.push(c);
                    } else {
                        break;
                    }
                }
            }
        }
        out
    }

    fn consume_numeric(&mut self) -> Token {
        let (has_sign, sign) = match self.byte_at(0) {
            Some(b'-') => (true, -1.0),
            Some(b'+') => (true, 1.0),
            _ => (false, 1.0),
        };
        if has_sign {
            self.pos += 1;
        }
        let mut integral: f64 = 0.0;
        while let Some(b) = self.byte_at(0) {
            if b.is_ascii_digit() {
                integral = integral * 10.0 + (b - b'0') as f64;
                self.pos += 1;
            } else {
                break;
            }
        }
        let mut is_integer = true;
        let mut fractional: f64 = 0.0;
        if self.byte_at(0) == Some(b'.') && self.byte_at(1).map_or(false, |b| b.is_ascii_digit()) {
            is_integer = false;
            self.pos += 1;
            let mut factor = 0.1;
            while let Some(b) = self.byte_at(0) {
                if b.is_ascii_digit() {
                    fractional += (b - b'0') as f64 * factor;
                    factor *= 0.1;
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        let mut value = sign * (integral + fractional);
        if matches!(self.byte_at(0), Some(b'e') | Some(b'E')) {
            let d1 = self.byte_at(1).map_or(false, |b| b.is_ascii_digit());
            let d2 = matches!(self.byte_at(1), Some(b'+') | Some(b'-'))
                && self.byte_at(2).map_or(false, |b| b.is_ascii_digit());
            if d1 || d2 {
                is_integer = false;
                self.pos += 1;
                let (esign_present, esign) = match self.byte_at(0) {
                    Some(b'-') => (true, -1.0),
                    Some(b'+') => (true, 1.0),
                    _ => (false, 1.0),
                };
                if esign_present {
                    self.pos += 1;
                }
                let mut exponent: f64 = 0.0;
                while let Some(b) = self.byte_at(0) {
                    if b.is_ascii_digit() {
                        exponent = exponent * 10.0 + (b - b'0') as f64;
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                value *= 10f64.powf(esign * exponent);
            }
        }
        let int_value = if is_integer {
            Some(if value >= i32::MAX as f64 {
                i32::MAX
            } else if value <= i32::MIN as f64 {
                i32::MIN
            } else {
                value as i32
            })
        } else {
            None
        };
        if self.byte_at(0) == Some(b'%') {
            self.pos += 1;
            return Token::Percentage { has_sign, unit_value: value / 100.0, int_value };
        }
        if self.is_ident_start() {
            let unit = self.consume_name();
            Token::Dimension { has_sign, value, int_value, unit }
        } else {
            Token::Number { has_sign, value, int_value }
        }
    }

    fn consume_string(&mut self, quote: u8) -> Token {
        let mut out = String::new();
        loop {
            match self.byte_at(0) {
                None => return Token::QuotedString(out),
                Some(b) if b == quote => {
                    self.pos += 1;
                    return Token::QuotedString(out);
                }
                Some(b'\\') => {
                    self.pos += 1;
                    match self.byte_at(0) {
                        None => {}
                        Some(b'\n') | Some(b'\x0C') => self.pos += 1,
                        Some(b'\r') => {
                            self.pos += 1;
                            if self.byte_at(0) == Some(b'\n') {
                                self.pos += 1;
                            }
                        }
                        Some(_) => {
                            let c = self.consume_escape();
                            out.push(c);
                        }
                    }
                }
                Some(b) if is_newline(b) => return Token::BadString,
                Some(0) => {
                    self.pos += 1;
                    out.push('\u{FFFD}');
                }
                Some(_) => {
                    let c = self.next_char();
                    out.push(c);
                }
            }
        }
    }

    fn consume_ident_like(&mut self) -> Token {
        let value = self.consume_name();
        if self.byte_at(0) == Some(b'(') {
            self.pos += 1;
            if value.eq_ignore_ascii_case("url") {
                return self.consume_unquoted_url().unwrap_or(Token::Function(value));
            }
            Token::Function(value)
        } else {
            Token::Ident(value)
        }
    }

    fn consume_unquoted_url(&mut self) -> Option<Token> {
        // Skip whitespace; if a quote follows, this is a normal function.
        let start = self.pos;
        while let Some(b) = self.byte_at(0) {
            if is_ws_byte(b) {
                self.pos += 1;
            } else {
                break;
            }
        }
        match self.byte_at(0) {
            Some(b'"') | Some(b'\'') => {
                self.pos = start;
                return None;
            }
            None => return Some(Token::UnquotedUrl(String::new())),
            Some(b')') => {
                self.pos += 1;
                return Some(Token::UnquotedUrl(String::new()));
            }
            _ => {}
        }
        let mut out = String::new();
        loop {
            match self.byte_at(0) {
                None => return Some(Token::UnquotedUrl(out)),
                Some(b')') => {
                    self.pos += 1;
                    return Some(Token::UnquotedUrl(out));
                }
                Some(b) if is_ws_byte(b) => {
                    while let Some(b) = self.byte_at(0) {
                        if is_ws_byte(b) {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    match self.byte_at(0) {
                        None => return Some(Token::UnquotedUrl(out)),
                        Some(b')') => {
                            self.pos += 1;
                            return Some(Token::UnquotedUrl(out));
                        }
                        _ => return Some(self.consume_bad_url()),
                    }
                }
                Some(b'"') | Some(b'\'') | Some(b'(') => return Some(self.consume_bad_url()),
                Some(b) if b < 0x20 || b == 0x7F => {
                    if b == 0 {
                        self.pos += 1;
                        out.push('\u{FFFD}');
                    } else {
                        return Some(self.consume_bad_url());
                    }
                }
                Some(b'\\') => {
                    if self.has_newline_at(1) {
                        return Some(self.consume_bad_url());
                    }
                    self.pos += 1;
                    let c = self.consume_escape();
                    out.push(c);
                }
                Some(_) => {
                    let c = self.next_char();
                    out.push(c);
                }
            }
        }
    }

    fn consume_bad_url(&mut self) -> Token {
        loop {
            match self.byte_at(0) {
                None => return Token::BadUrl,
                Some(b')') => {
                    self.pos += 1;
                    return Token::BadUrl;
                }
                Some(b'\\') => {
                    self.pos += 1;
                    if !self.eof() {
                        self.next_char();
                    }
                }
                Some(_) => {
                    self.next_char();
                }
            }
        }
    }

    fn next_token(&mut self) -> Option<Token> {
        let b = self.byte_at(0)?;
        let tok = match b {
            b' ' | b'\t' | b'\n' | b'\r' | b'\x0C' => {
                while let Some(b) = self.byte_at(0) {
                    if is_ws_byte(b) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Token::WhiteSpace
            }
            b'"' => {
                self.pos += 1;
                self.consume_string(b'"')
            }
            b'\'' => {
                self.pos += 1;
                self.consume_string(b'\'')
            }
            b'#' => {
                self.pos += 1;
                if self.is_ident_start() {
                    Token::IDHash(self.consume_name())
                } else {
                    match self.byte_at(0) {
                        Some(c) if is_name_char(c) => Token::Hash(self.consume_name()),
                        Some(b'\\') if !self.has_newline_at(1) => Token::Hash(self.consume_name()),
                        _ => Token::Delim('#'),
                    }
                }
            }
            b'$' => {
                if self.byte_at(1) == Some(b'=') {
                    self.pos += 2;
                    Token::SuffixMatch
                } else {
                    self.pos += 1;
                    Token::Delim('$')
                }
            }
            b'(' => {
                self.pos += 1;
                Token::ParenthesisBlock
            }
            b')' => {
                self.pos += 1;
                Token::CloseParenthesis
            }
            b'*' => {
                if self.byte_at(1) == Some(b'=') {
                    self.pos += 2;
                    Token::SubstringMatch
                } else {
                    self.pos += 1;
                    Token::Delim('*')
                }
            }
            b'+' => {
                let d1 = self.byte_at(1).map_or(false, |b| b.is_ascii_digit());
                let d2 = self.byte_at(1) == Some(b'.') && self.byte_at(2).map_or(false, |b| b.is_ascii_digit());
                if d1 || d2 {
                    self.consume_numeric()
                } else {
                    self.pos += 1;
                    Token::Delim('+')
                }
            }
            b',' => {
                self.pos += 1;
                Token::Comma
            }
            b'-' => {
                let d1 = self.byte_at(1).map_or(false, |b| b.is_ascii_digit());
                let d2 = self.byte_at(1) == Some(b'.') && self.byte_at(2).map_or(false, |b| b.is_ascii_digit());
                if d1 || d2 {
                    self.consume_numeric()
                } else if self.starts_with(b"-->") {
                    self.pos += 3;
                    Token::CDC
                } else if self.is_ident_start() {
                    self.consume_ident_like()
                } else {
                    self.pos += 1;
                    Token::Delim('-')
                }
            }
            b'.' => {
                if self.byte_at(1).map_or(false, |b| b.is_ascii_digit()) {
                    self.consume_numeric()
                } else {
                    self.pos += 1;
                    Token::Delim('.')
                }
            }
            b'/' => {
                if self.byte_at(1) == Some(b'*') {
                    self.pos += 2;
                    loop {
                        match self.byte_at(0) {
                            None => break,
                            Some(b'*') if self.byte_at(1) == Some(b'/') => {
                                self.pos += 2;
                                break;
                            }
                            Some(_) => self.pos += 1,
                        }
                    }
                    Token::Comment
                } else {
                    self.pos += 1;
                    Token::Delim('/')
                }
            }
            b'0'..=b'9' => self.consume_numeric(),
            b':' => {
                self.pos += 1;
                Token::Colon
            }
            b';' => {
                self.pos += 1;
                Token::Semicolon
            }
            b'<' => {
                if self.starts_with(b"<!--") {
                    self.pos += 4;
                    Token::CDO
                } else {
                    self.pos += 1;
                    Token::Delim('<')
                }
            }
            b'@' => {
                self.pos += 1;
                if self.is_ident_start() {
                    Token::AtKeyword(self.consume_name())
                } else {
                    Token::Delim('@')
                }
            }
            b'[' => {
                self.pos += 1;
                Token::SquareBracketBlock
            }
            b'\\' => {
                if !self.has_newline_at(1) {
                    self.consume_ident_like()
                } else {
                    self.pos += 1;
                    Token::Delim('\\')
                }
            }
            b']' => {
                self.pos += 1;
                Token::CloseSquareBracket
            }
            b'^' => {
                if self.byte_at(1) == Some(b'=') {
                    self.pos += 2;
                    Token::PrefixMatch
                } else {
                    self.pos += 1;
                    Token::Delim('^')
                }
            }
            b'{' => {
                self.pos += 1;
                Token::CurlyBracketBlock
            }
            b'|' => {
                if self.byte_at(1) == Some(b'=') {
                    self.pos += 2;
                    Token::DashMatch
                } else {
                    self.pos += 1;
                    Token::Delim('|')
                }
            }
            b'}' => {
                self.pos += 1;
                Token::CloseCurlyBracket
            }
            b'~' => {
                if self.byte_at(1) == Some(b'=') {
                    self.pos += 2;
                    Token::IncludeMatch
                } else {
                    self.pos += 1;
                    Token::Delim('~')
                }
            }
            b'a'..=b'z' | b'A'..=b'Z' | b'_' | 0 => self.consume_ident_like(),
            b if !b.is_ascii() => self.consume_ident_like(),
            _ => {
                let c = self.next_char();
                Token::Delim(c)
            }
        };
        Some(tok)
    }
}

pub fn tokenize(src: &str) -> Vec<Token> {
    let mut t = Tokenizer { input: src.as_bytes(), pos: 0, src };
    let mut out = Vec::new();
    while let Some(tok) = t.next_token() {
        out.push(tok);
    }
    out
}
