//! CSS selector parsing and matching.

use crate::css_tokenizer::{tokenize, BlockType, Token};
use crate::dom::*;

// ---------------------------------------------------------------------------
// Token stream parser with nested block / delimiter support.
// ---------------------------------------------------------------------------

struct Parser<'t> {
    tokens: &'t [Token],
    block_end: &'t [usize],
    pos: usize,
    end: usize,
    stop_at_comma: bool,
    at_start_of: Option<usize>,
}

#[derive(Clone, Copy)]
struct State {
    pos: usize,
    at_start_of: Option<usize>,
}

struct ParseError;

type PResult<T> = Result<T, ParseError>;

fn compute_block_ends(tokens: &[Token]) -> Vec<usize> {
    let mut ends = vec![tokens.len(); tokens.len()];
    for i in 0..tokens.len() {
        if let Some(bt) = tokens[i].opening_block() {
            let mut stack: Vec<BlockType> = vec![bt];
            let mut j = i + 1;
            let mut found = tokens.len();
            while j < tokens.len() {
                if let Some(cb) = tokens[j].closing_block() {
                    if *stack.last().unwrap() == cb {
                        stack.pop();
                        if stack.is_empty() {
                            found = j;
                            break;
                        }
                    }
                }
                if let Some(ob) = tokens[j].opening_block() {
                    stack.push(ob);
                }
                j += 1;
            }
            ends[i] = found;
        }
    }
    ends
}

impl<'t> Parser<'t> {
    fn state(&self) -> State {
        State { pos: self.pos, at_start_of: self.at_start_of }
    }

    fn reset(&mut self, s: State) {
        self.pos = s.pos;
        self.at_start_of = s.at_start_of;
    }

    fn skip_pending_block(&mut self) {
        if let Some(i) = self.at_start_of.take() {
            let close = self.block_end[i];
            self.pos = (close + 1).min(self.end.max(close + 1)).min(self.tokens.len());
            if self.pos > self.end {
                self.pos = self.end;
            }
        }
    }

    fn next_including_whitespace(&mut self) -> PResult<&'t Token> {
        self.skip_pending_block();
        loop {
            if self.pos >= self.end {
                return Err(ParseError);
            }
            let tok = &self.tokens[self.pos];
            if self.stop_at_comma && *tok == Token::Comma {
                return Err(ParseError);
            }
            self.pos += 1;
            if *tok == Token::Comment {
                continue;
            }
            if tok.opening_block().is_some() {
                self.at_start_of = Some(self.pos - 1);
            }
            return Ok(tok);
        }
    }

    fn skip_whitespace(&mut self) {
        self.skip_pending_block();
        while self.pos < self.end {
            let tok = &self.tokens[self.pos];
            if self.stop_at_comma && *tok == Token::Comma {
                return;
            }
            match tok {
                Token::WhiteSpace | Token::Comment => self.pos += 1,
                _ => return,
            }
        }
    }

    fn next(&mut self) -> PResult<&'t Token> {
        self.skip_whitespace();
        self.next_including_whitespace()
    }

    fn expect_exhausted(&mut self) -> PResult<()> {
        match self.next() {
            Ok(_) => Err(ParseError),
            Err(_) => Ok(()),
        }
    }

    fn parse_nested_block<T>(&mut self, f: impl FnOnce(&mut Parser<'t>) -> PResult<T>) -> PResult<T> {
        let open = self.at_start_of.take().expect("parse_nested_block without block");
        let close = self.block_end[open];
        let mut nested = Parser {
            tokens: self.tokens,
            block_end: self.block_end,
            pos: open + 1,
            end: close.min(self.tokens.len()),
            stop_at_comma: false,
            at_start_of: None,
        };
        let result = f(&mut nested).and_then(|v| nested.expect_exhausted().map(|_| v));
        self.pos = (close + 1).min(self.tokens.len());
        if self.pos > self.end {
            self.pos = self.end;
        }
        self.at_start_of = None;
        result
    }

    fn parse_until_before_comma<T>(&mut self, f: impl FnOnce(&mut Parser<'t>) -> PResult<T>) -> PResult<T> {
        self.skip_pending_block();
        let start = self.pos;
        let mut nested = Parser {
            tokens: self.tokens,
            block_end: self.block_end,
            pos: start,
            end: self.end,
            stop_at_comma: true,
            at_start_of: None,
        };
        let result = f(&mut nested).and_then(|v| nested.expect_exhausted().map(|_| v));
        // Advance to the comma (or end), skipping blocks.
        let mut i = start;
        while i < self.end {
            let tok = &self.tokens[i];
            if *tok == Token::Comma {
                break;
            }
            if tok.opening_block().is_some() {
                i = self.block_end[i] + 1;
            } else {
                i += 1;
            }
        }
        self.pos = i.min(self.end);
        self.at_start_of = None;
        result
    }
}

// ---------------------------------------------------------------------------
// Selector AST
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Combinator {
    Child,
    Descendant,
    NextSibling,
    LaterSibling,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AttrOperator {
    Equal,
    Includes,
    DashMatch,
    Prefix,
    Substring,
    Suffix,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CaseSensitivity {
    CaseSensitive,
    AsciiCaseInsensitive,
    AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument,
    ExplicitCaseSensitive,
}

#[derive(Debug, Clone, PartialEq)]
pub enum NsConstraint {
    /// `[attr]` / `[|attr]`: attribute in no namespace.
    NoNamespace,
    /// `[*|attr]`
    Any,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PseudoClass {
    AnyLink,
    Link,
    Visited,
    Active,
    Focus,
    Hover,
    Enabled,
    Disabled,
    Checked,
    Indeterminate,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Component {
    LocalName { name: String, lower_name: String },
    ExplicitUniversalType,
    ExplicitAnyNamespace,
    ExplicitNoNamespace,
    Id(String),
    Class(String),
    AttributeExists { local_name: String, local_name_lower: String, ns: NsConstraint },
    AttributeWithValue {
        local_name: String,
        local_name_lower: String,
        ns: NsConstraint,
        operator: AttrOperator,
        value: String,
        case_sensitivity: CaseSensitivity,
        never_matches: bool,
    },
    FirstChild,
    LastChild,
    OnlyChild,
    Root,
    Empty,
    Scope,
    FirstOfType,
    LastOfType,
    OnlyOfType,
    NthChild(i32, i32),
    NthLastChild(i32, i32),
    NthOfType(i32, i32),
    NthLastOfType(i32, i32),
    Negation(Vec<Component>),
    NonTSPseudo(PseudoClass),
}

#[derive(Debug, Clone)]
pub struct Compound {
    pub components: Vec<Component>,
}

#[derive(Debug, Clone)]
pub struct Selector {
    /// Compounds from left to right, each followed by the combinator to its right (None for the last).
    pub parts: Vec<(Compound, Option<Combinator>)>,
}

#[derive(Debug, Clone)]
pub struct SelectorList(pub Vec<Selector>);

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

const CASE_INSENSITIVE_HTML_ATTRS: &[&str] = &[
    "accept", "accept-charset", "align", "alink", "axis", "bgcolor", "charset", "checked", "clear", "codetype",
    "color", "compact", "declare", "defer", "dir", "direction", "disabled", "enctype", "face", "frame", "hreflang",
    "http-equiv", "lang", "language", "link", "media", "method", "multiple", "nohref", "noresize", "noshade",
    "nowrap", "readonly", "rel", "rev", "rules", "scope", "scrolling", "selected", "shape", "target", "text", "type",
    "valign", "valuetype", "vlink",
];

impl SelectorList {
    pub fn parse(input: &str) -> Result<SelectorList, ()> {
        let tokens = tokenize(input);
        let block_end = compute_block_ends(&tokens);
        let mut parser = Parser {
            tokens: &tokens,
            block_end: &block_end,
            pos: 0,
            end: tokens.len(),
            stop_at_comma: false,
            at_start_of: None,
        };
        let mut list = Vec::new();
        loop {
            let sel = parser.parse_until_before_comma(|p| parse_selector(p)).map_err(|_| ())?;
            list.push(sel);
            match parser.next() {
                Err(_) => return Ok(SelectorList(list)),
                Ok(Token::Comma) => continue,
                Ok(_) => return Err(()),
            }
        }
    }
}

fn parse_selector(input: &mut Parser) -> PResult<Selector> {
    let mut parts: Vec<(Compound, Option<Combinator>)> = Vec::new();
    'outer: loop {
        let compound = parse_compound_selector(input)?;
        let compound = match compound {
            Some(c) => c,
            None => return Err(ParseError), // empty selector or dangling combinator
        };
        parts.push((compound, None));
        // Parse a combinator.
        let combinator;
        let mut any_whitespace = false;
        loop {
            let before = input.state();
            match input.next_including_whitespace() {
                Err(_) => break 'outer,
                Ok(Token::WhiteSpace) => {
                    any_whitespace = true;
                    continue;
                }
                Ok(Token::Delim('>')) => {
                    combinator = Combinator::Child;
                    break;
                }
                Ok(Token::Delim('+')) => {
                    combinator = Combinator::NextSibling;
                    break;
                }
                Ok(Token::Delim('~')) => {
                    combinator = Combinator::LaterSibling;
                    break;
                }
                Ok(_) => {
                    input.reset(before);
                    if any_whitespace {
                        combinator = Combinator::Descendant;
                        break;
                    } else {
                        break 'outer;
                    }
                }
            }
        }
        parts.last_mut().unwrap().1 = Some(combinator);
    }
    Ok(Selector { parts })
}

fn parse_compound_selector(input: &mut Parser) -> PResult<Option<Compound>> {
    input.skip_whitespace();
    let mut components = Vec::new();
    let mut empty = true;
    if parse_type_selector(input, &mut components)? {
        empty = false;
    }
    loop {
        match parse_one_simple_selector(input, false)? {
            None => break,
            Some(c) => {
                empty = false;
                components.push(c);
            }
        }
    }
    if empty {
        Ok(None)
    } else {
        Ok(Some(Compound { components }))
    }
}

enum QNamePrefix {
    ImplicitNoNamespace,
    ImplicitAnyNamespace,
    ExplicitNoNamespace,
    ExplicitAnyNamespace,
}

enum OptionalQName {
    Some(QNamePrefix, Option<String>),
    None,
}

fn parse_qualified_name(input: &mut Parser, in_attr_selector: bool) -> PResult<OptionalQName> {
    let start = input.state();
    let explicit_namespace = |input: &mut Parser, ns: QNamePrefix| -> PResult<OptionalQName> {
        match input.next_including_whitespace() {
            Ok(Token::Delim('*')) if !in_attr_selector => Ok(OptionalQName::Some(ns, None)),
            Ok(Token::Ident(local)) => Ok(OptionalQName::Some(ns, Some(local.clone()))),
            _ => Err(ParseError),
        }
    };
    match input.next_including_whitespace() {
        Ok(Token::Ident(value)) => {
            let after_ident = input.state();
            match input.next_including_whitespace() {
                Ok(Token::Delim('|')) => {
                    // Namespace prefixes are never declared: error.
                    Err(ParseError)
                }
                _ => {
                    input.reset(after_ident);
                    if in_attr_selector {
                        Ok(OptionalQName::Some(QNamePrefix::ImplicitNoNamespace, Some(value.clone())))
                    } else {
                        Ok(OptionalQName::Some(QNamePrefix::ImplicitAnyNamespace, Some(value.clone())))
                    }
                }
            }
        }
        Ok(Token::Delim('*')) => {
            let after_star = input.state();
            match input.next_including_whitespace() {
                Ok(Token::Delim('|')) => explicit_namespace(input, QNamePrefix::ExplicitAnyNamespace),
                result => {
                    let is_err = result.is_err();
                    input.reset(after_star);
                    if in_attr_selector {
                        let _ = is_err;
                        Err(ParseError)
                    } else {
                        Ok(OptionalQName::Some(QNamePrefix::ImplicitAnyNamespace, None))
                    }
                }
            }
        }
        Ok(Token::Delim('|')) => explicit_namespace(input, QNamePrefix::ExplicitNoNamespace),
        Ok(_) => {
            input.reset(start);
            Ok(OptionalQName::None)
        }
        Err(_) => {
            input.reset(start);
            Err(ParseError)
        }
    }
}

/// Returns Ok(true) if a type selector was parsed.
fn parse_type_selector(input: &mut Parser, sink: &mut Vec<Component>) -> PResult<bool> {
    match parse_qualified_name(input, false) {
        Err(_) => {
            // EndOfInput → no type selector (other errors can't happen here except namespace ones).
            // Distinguish: if we're at EOF treat as no type selector.
            let st = input.state();
            let at_eof = input.next_including_whitespace().is_err();
            input.reset(st);
            if at_eof {
                Ok(false)
            } else {
                Err(ParseError)
            }
        }
        Ok(OptionalQName::None) => Ok(false),
        Ok(OptionalQName::Some(ns, local)) => {
            match ns {
                QNamePrefix::ImplicitAnyNamespace => {}
                QNamePrefix::ExplicitNoNamespace => sink.push(Component::ExplicitNoNamespace),
                QNamePrefix::ExplicitAnyNamespace => {
                    // No default namespace: equivalent to implicit any namespace.
                }
                QNamePrefix::ImplicitNoNamespace => unreachable!(),
            }
            match local {
                Some(name) => {
                    let lower = name.to_ascii_lowercase();
                    sink.push(Component::LocalName { name, lower_name: lower });
                }
                None => sink.push(Component::ExplicitUniversalType),
            }
            Ok(true)
        }
    }
}

fn is_css2_pseudo_element(name: &str) -> bool {
    name.eq_ignore_ascii_case("before")
        || name.eq_ignore_ascii_case("after")
        || name.eq_ignore_ascii_case("first-line")
        || name.eq_ignore_ascii_case("first-letter")
}

fn parse_one_simple_selector(input: &mut Parser, inside_negation: bool) -> PResult<Option<Component>> {
    let start = input.state();
    match input.next_including_whitespace() {
        Ok(Token::IDHash(id)) => Ok(Some(Component::Id(id.clone()))),
        Ok(Token::Delim('.')) => match input.next_including_whitespace()? {
            Token::Ident(class) => Ok(Some(Component::Class(class.clone()))),
            _ => Err(ParseError),
        },
        Ok(Token::SquareBracketBlock) => {
            let attr = input.parse_nested_block(|input| parse_attribute_selector(input))?;
            Ok(Some(attr))
        }
        Ok(Token::Colon) => {
            let (is_single_colon, next_token) = match input.next_including_whitespace()? {
                Token::Colon => (false, input.next_including_whitespace()?.clone()),
                t => (true, t.clone()),
            };
            let (name, is_functional) = match next_token {
                Token::Ident(name) => (name, false),
                Token::Function(name) => (name, true),
                _ => return Err(ParseError),
            };
            let is_pseudo_element = !is_single_colon || is_css2_pseudo_element(&name);
            if is_pseudo_element {
                // Pseudo-elements are not supported.
                return Err(ParseError);
            }
            let pc = if is_functional {
                input.parse_nested_block(|input| parse_functional_pseudo_class(input, &name, inside_negation))?
            } else {
                parse_simple_pseudo_class(&name)?
            };
            Ok(Some(pc))
        }
        _ => {
            input.reset(start);
            Ok(None)
        }
    }
}

fn parse_simple_pseudo_class(name: &str) -> PResult<Component> {
    let lower = name.to_ascii_lowercase();
    Ok(match lower.as_str() {
        "first-child" => Component::FirstChild,
        "last-child" => Component::LastChild,
        "only-child" => Component::OnlyChild,
        "root" => Component::Root,
        "empty" => Component::Empty,
        "scope" => Component::Scope,
        "first-of-type" => Component::FirstOfType,
        "last-of-type" => Component::LastOfType,
        "only-of-type" => Component::OnlyOfType,
        "any-link" => Component::NonTSPseudo(PseudoClass::AnyLink),
        "link" => Component::NonTSPseudo(PseudoClass::Link),
        "visited" => Component::NonTSPseudo(PseudoClass::Visited),
        "active" => Component::NonTSPseudo(PseudoClass::Active),
        "focus" => Component::NonTSPseudo(PseudoClass::Focus),
        "hover" => Component::NonTSPseudo(PseudoClass::Hover),
        "enabled" => Component::NonTSPseudo(PseudoClass::Enabled),
        "disabled" => Component::NonTSPseudo(PseudoClass::Disabled),
        "checked" => Component::NonTSPseudo(PseudoClass::Checked),
        "indeterminate" => Component::NonTSPseudo(PseudoClass::Indeterminate),
        _ => return Err(ParseError),
    })
}

fn parse_functional_pseudo_class(input: &mut Parser, name: &str, inside_negation: bool) -> PResult<Component> {
    let lower = name.to_ascii_lowercase();
    match lower.as_str() {
        "nth-child" => {
            let (a, b) = parse_nth(input)?;
            Ok(Component::NthChild(a, b))
        }
        "nth-of-type" => {
            let (a, b) = parse_nth(input)?;
            Ok(Component::NthOfType(a, b))
        }
        "nth-last-child" => {
            let (a, b) = parse_nth(input)?;
            Ok(Component::NthLastChild(a, b))
        }
        "nth-last-of-type" => {
            let (a, b) = parse_nth(input)?;
            Ok(Component::NthLastOfType(a, b))
        }
        "not" => {
            if inside_negation {
                return Err(ParseError);
            }
            parse_negation(input)
        }
        _ => Err(ParseError),
    }
}

fn parse_negation(input: &mut Parser) -> PResult<Component> {
    let mut sequence = Vec::new();
    input.skip_whitespace();
    let is_type_sel = match parse_type_selector(input, &mut sequence) {
        Ok(r) => r,
        Err(_) => return Err(ParseError),
    };
    if !is_type_sel {
        match parse_one_simple_selector(input, true)? {
            Some(c) => sequence.push(c),
            None => return Err(ParseError),
        }
    }
    Ok(Component::Negation(sequence))
}

fn parse_attribute_selector(input: &mut Parser) -> PResult<Component> {
    input.skip_whitespace();
    let (ns, local_name) = match parse_qualified_name(input, true)? {
        OptionalQName::None => return Err(ParseError),
        OptionalQName::Some(_, None) => return Err(ParseError),
        OptionalQName::Some(ns, Some(ln)) => {
            let ns = match ns {
                QNamePrefix::ImplicitNoNamespace | QNamePrefix::ExplicitNoNamespace => NsConstraint::NoNamespace,
                QNamePrefix::ExplicitAnyNamespace => NsConstraint::Any,
                QNamePrefix::ImplicitAnyNamespace => unreachable!(),
            };
            (ns, ln)
        }
    };
    let local_name_lower = local_name.to_ascii_lowercase();
    let operator = match input.next() {
        Err(_) => {
            return Ok(Component::AttributeExists { local_name, local_name_lower, ns });
        }
        Ok(Token::Delim('=')) => AttrOperator::Equal,
        Ok(Token::IncludeMatch) => AttrOperator::Includes,
        Ok(Token::DashMatch) => AttrOperator::DashMatch,
        Ok(Token::PrefixMatch) => AttrOperator::Prefix,
        Ok(Token::SubstringMatch) => AttrOperator::Substring,
        Ok(Token::SuffixMatch) => AttrOperator::Suffix,
        Ok(_) => return Err(ParseError),
    };
    let value = match input.next() {
        Ok(Token::Ident(s)) | Ok(Token::QuotedString(s)) => s.clone(),
        _ => return Err(ParseError),
    };
    let never_matches = match operator {
        AttrOperator::Equal | AttrOperator::DashMatch => false,
        AttrOperator::Includes => value.is_empty() || value.contains(SELECTOR_WHITESPACE),
        AttrOperator::Prefix | AttrOperator::Substring | AttrOperator::Suffix => value.is_empty(),
    };
    let mut case_sensitivity = parse_attribute_flags(input)?;
    if case_sensitivity == CaseSensitivity::CaseSensitive
        && ns == NsConstraint::NoNamespace
        && CASE_INSENSITIVE_HTML_ATTRS.contains(&local_name_lower.as_str())
    {
        case_sensitivity = CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument;
    }
    Ok(Component::AttributeWithValue {
        local_name,
        local_name_lower,
        ns,
        operator,
        value,
        case_sensitivity,
        never_matches,
    })
}

fn parse_attribute_flags(input: &mut Parser) -> PResult<CaseSensitivity> {
    let tok = match input.next() {
        Ok(t) => t,
        Err(_) => return Ok(CaseSensitivity::CaseSensitive),
    };
    match tok {
        Token::Ident(i) => {
            if i.eq_ignore_ascii_case("i") {
                Ok(CaseSensitivity::AsciiCaseInsensitive)
            } else if i.eq_ignore_ascii_case("s") {
                Ok(CaseSensitivity::ExplicitCaseSensitive)
            } else {
                Err(ParseError)
            }
        }
        _ => Err(ParseError),
    }
}

const SELECTOR_WHITESPACE: &[char] = &[' ', '\t', '\n', '\r', '\x0C'];

// ---- An+B parsing ----

fn parse_nth(input: &mut Parser) -> PResult<(i32, i32)> {
    match input.next()? {
        Token::Number { int_value: Some(b), .. } => Ok((0, *b)),
        Token::Dimension { int_value: Some(a), unit, .. } => {
            let a = *a;
            if unit.eq_ignore_ascii_case("n") {
                parse_b(input, a)
            } else if unit.eq_ignore_ascii_case("n-") {
                parse_signless_b(input, a, -1)
            } else {
                match parse_n_dash_digits(unit) {
                    Ok(b) => Ok((a, b)),
                    Err(()) => Err(ParseError),
                }
            }
        }
        Token::Ident(value) => {
            if value.eq_ignore_ascii_case("even") {
                Ok((2, 0))
            } else if value.eq_ignore_ascii_case("odd") {
                Ok((2, 1))
            } else if value.eq_ignore_ascii_case("n") {
                parse_b(input, 1)
            } else if value.eq_ignore_ascii_case("-n") {
                parse_b(input, -1)
            } else if value.eq_ignore_ascii_case("n-") {
                parse_signless_b(input, 1, -1)
            } else if value.eq_ignore_ascii_case("-n-") {
                parse_signless_b(input, -1, -1)
            } else {
                let (slice, a) = if let Some(rest) = value.strip_prefix('-') { (rest, -1) } else { (value.as_str(), 1) };
                match parse_n_dash_digits(slice) {
                    Ok(b) => Ok((a, b)),
                    Err(()) => Err(ParseError),
                }
            }
        }
        Token::Delim('+') => match input.next_including_whitespace()? {
            Token::Ident(value) => {
                if value.eq_ignore_ascii_case("n") {
                    parse_b(input, 1)
                } else if value.eq_ignore_ascii_case("n-") {
                    parse_signless_b(input, 1, -1)
                } else {
                    match parse_n_dash_digits(value) {
                        Ok(b) => Ok((1, b)),
                        Err(()) => Err(ParseError),
                    }
                }
            }
            _ => Err(ParseError),
        },
        _ => Err(ParseError),
    }
}

fn parse_b(input: &mut Parser, a: i32) -> PResult<(i32, i32)> {
    let start = input.state();
    match input.next() {
        Ok(Token::Delim('+')) => parse_signless_b(input, a, 1),
        Ok(Token::Delim('-')) => parse_signless_b(input, a, -1),
        Ok(Token::Number { has_sign: true, int_value: Some(b), .. }) => Ok((a, *b)),
        _ => {
            input.reset(start);
            Ok((a, 0))
        }
    }
}

fn parse_signless_b(input: &mut Parser, a: i32, b_sign: i32) -> PResult<(i32, i32)> {
    match input.next()? {
        Token::Number { has_sign: false, int_value: Some(b), .. } => Ok((a, b_sign * *b)),
        _ => Err(ParseError),
    }
}

fn parse_n_dash_digits(s: &str) -> Result<i32, ()> {
    let bytes = s.as_bytes();
    if bytes.len() >= 3 && bytes[..2].eq_ignore_ascii_case(b"n-") && bytes[2..].iter().all(|c| c.is_ascii_digit()) {
        // Include the minus sign.
        Ok(parse_number_saturate(&s[1..]))
    } else {
        Err(())
    }
}

fn parse_number_saturate(s: &str) -> i32 {
    // s is like "-123".
    let neg = s.starts_with('-');
    let digits = if neg { &s[1..] } else { s };
    let mut v: i64 = 0;
    for c in digits.bytes() {
        v = v * 10 + (c - b'0') as i64;
        if v > i32::MAX as i64 + 1 {
            v = i32::MAX as i64 + 1;
        }
    }
    let v = if neg { -v } else { v };
    v.clamp(i32::MIN as i64, i32::MAX as i64) as i32
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

fn parent_element(node: &NodeRef) -> Option<NodeRef> {
    node.parent().filter(|p| p.is_element())
}

fn prev_sibling_element(node: &NodeRef) -> Option<NodeRef> {
    let mut cur = node.previous_sibling();
    while let Some(n) = cur {
        if n.is_element() {
            return Some(n);
        }
        cur = n.previous_sibling();
    }
    None
}

fn next_sibling_element(node: &NodeRef) -> Option<NodeRef> {
    let mut cur = node.next_sibling();
    while let Some(n) = cur {
        if n.is_element() {
            return Some(n);
        }
        cur = n.next_sibling();
    }
    None
}

fn is_html_element(node: &NodeRef) -> bool {
    node.as_element().map_or(false, |e| e.name.ns == NS_HTML)
}

fn case_eq(a: &[u8], b: &[u8], insensitive: bool) -> bool {
    if insensitive {
        a.eq_ignore_ascii_case(b)
    } else {
        a == b
    }
}

fn eval_attr_op(element_value: &str, operator: AttrOperator, expected: &str, insensitive: bool) -> bool {
    let e = element_value.as_bytes();
    let s = expected.as_bytes();
    match operator {
        AttrOperator::Equal => case_eq(e, s, insensitive),
        AttrOperator::Prefix => e.len() >= s.len() && case_eq(&e[..s.len()], s, insensitive),
        AttrOperator::Suffix => e.len() >= s.len() && case_eq(&e[e.len() - s.len()..], s, insensitive),
        AttrOperator::Substring => {
            if insensitive {
                element_value.to_ascii_lowercase().contains(&expected.to_ascii_lowercase())
            } else {
                element_value.contains(expected)
            }
        }
        AttrOperator::Includes => {
            element_value.split(SELECTOR_WHITESPACE).any(|part| case_eq(part.as_bytes(), s, insensitive))
        }
        AttrOperator::DashMatch => {
            case_eq(e, s, insensitive) || (e.get(s.len()) == Some(&b'-') && case_eq(&e[..s.len()], s, insensitive))
        }
    }
}

fn attr_matches(
    element: &ElementData,
    ns: &NsConstraint,
    local_name: &str,
    f: &dyn Fn(&str) -> bool,
) -> bool {
    let attrs = element.attributes.borrow();
    match ns {
        NsConstraint::Any => attrs.map.iter().any(|(k, a)| k.local == local_name && f(&a.value)),
        NsConstraint::NoNamespace => attrs.get(local_name).map_or(false, |v| f(v)),
    }
}

fn nth_child_index(node: &NodeRef, is_of_type: bool, from_end: bool) -> i32 {
    let mut index = 1;
    let name = &node.as_element().unwrap().name;
    let mut cur = if from_end { node.next_sibling() } else { node.previous_sibling() };
    while let Some(n) = cur {
        if let Some(e) = n.as_element() {
            if !is_of_type || e.name == *name {
                index += 1;
            }
        }
        cur = if from_end { n.next_sibling() } else { n.previous_sibling() };
    }
    index
}

fn matches_generic_nth_child(node: &NodeRef, a: i32, b: i32, is_of_type: bool, from_end: bool) -> bool {
    let index = nth_child_index(node, is_of_type, from_end);
    match index.checked_sub(b) {
        None => false,
        Some(an) => match an.checked_div(a) {
            Some(n) => n >= 0 && a.checked_mul(n) == Some(an),
            None => an == 0,
        },
    }
}

fn is_empty_element(node: &NodeRef) -> bool {
    node.children().all(|child| match &child.data {
        NodeData::Element(_) => false,
        NodeData::Text(t) => t.borrow().is_empty(),
        _ => true,
    })
}

fn is_root(node: &NodeRef) -> bool {
    match node.parent() {
        None => false,
        Some(p) => p.as_document().is_some(),
    }
}

fn matches_simple(component: &Component, node: &NodeRef) -> bool {
    let element = node.as_element().unwrap();
    let is_html = element.name.ns == NS_HTML;
    match component {
        Component::LocalName { name, lower_name } => {
            let n = if is_html { lower_name } else { name };
            element.name.local == *n
        }
        Component::ExplicitUniversalType | Component::ExplicitAnyNamespace => true,
        Component::ExplicitNoNamespace => element.name.ns.is_empty(),
        Component::Id(id) => element.attributes.borrow().get("id").map_or(false, |v| v == id),
        Component::Class(class) => element
            .attributes
            .borrow()
            .get("class")
            .map_or(false, |v| v.split(SELECTOR_WHITESPACE).any(|c| c == class)),
        Component::AttributeExists { local_name, local_name_lower, ns } => {
            let n = if is_html { local_name_lower } else { local_name };
            attr_matches(element, ns, n, &|_| true)
        }
        Component::AttributeWithValue { local_name, local_name_lower, ns, operator, value, case_sensitivity, never_matches } => {
            if *never_matches {
                return false;
            }
            let n = if is_html { local_name_lower } else { local_name };
            let insensitive = match case_sensitivity {
                CaseSensitivity::AsciiCaseInsensitive => true,
                CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument => is_html,
                _ => false,
            };
            attr_matches(element, ns, n, &|v| eval_attr_op(v, *operator, value, insensitive))
        }
        Component::NonTSPseudo(pc) => match pc {
            PseudoClass::AnyLink | PseudoClass::Link => {
                is_html
                    && matches!(element.name.local.as_str(), "a" | "area" | "link")
                    && element.attributes.borrow().contains("href")
            }
            _ => false,
        },
        Component::FirstChild => prev_sibling_element(node).is_none(),
        Component::LastChild => next_sibling_element(node).is_none(),
        Component::OnlyChild => prev_sibling_element(node).is_none() && next_sibling_element(node).is_none(),
        Component::Root => is_root(node),
        Component::Empty => is_empty_element(node),
        Component::Scope => is_root(node),
        Component::NthChild(a, b) => matches_generic_nth_child(node, *a, *b, false, false),
        Component::NthLastChild(a, b) => matches_generic_nth_child(node, *a, *b, false, true),
        Component::NthOfType(a, b) => matches_generic_nth_child(node, *a, *b, true, false),
        Component::NthLastOfType(a, b) => matches_generic_nth_child(node, *a, *b, true, true),
        Component::FirstOfType => matches_generic_nth_child(node, 0, 1, true, false),
        Component::LastOfType => matches_generic_nth_child(node, 0, 1, true, true),
        Component::OnlyOfType => {
            matches_generic_nth_child(node, 0, 1, true, false) && matches_generic_nth_child(node, 0, 1, true, true)
        }
        Component::Negation(list) => !list.iter().all(|c| matches_simple(c, node)),
    }
}

fn matches_compound(compound: &Compound, node: &NodeRef) -> bool {
    compound.components.iter().all(|c| matches_simple(c, node))
}

/// Match the selector's parts[..=idx] against the element, right to left.
fn matches_from(selector: &Selector, idx: usize, node: &NodeRef) -> bool {
    let (compound, _) = &selector.parts[idx];
    if !matches_compound(compound, node) {
        return false;
    }
    if idx == 0 {
        return true;
    }
    let combinator = selector.parts[idx - 1].1.unwrap();
    match combinator {
        Combinator::Child => match parent_element(node) {
            Some(p) => matches_from(selector, idx - 1, &p),
            None => false,
        },
        Combinator::Descendant => {
            let mut cur = parent_element(node);
            while let Some(p) = cur {
                if matches_from(selector, idx - 1, &p) {
                    return true;
                }
                cur = parent_element(&p);
            }
            false
        }
        Combinator::NextSibling => match prev_sibling_element(node) {
            Some(p) => matches_from(selector, idx - 1, &p),
            None => false,
        },
        Combinator::LaterSibling => {
            let mut cur = prev_sibling_element(node);
            while let Some(p) = cur {
                if matches_from(selector, idx - 1, &p) {
                    return true;
                }
                cur = prev_sibling_element(&p);
            }
            false
        }
    }
}

impl SelectorList {
    pub fn matches(&self, node: &NodeRef) -> bool {
        if !node.is_element() {
            return false;
        }
        self.0.iter().any(|s| matches_from(s, s.parts.len() - 1, node))
    }
}

/// Lazy iterator over matching elements in document order.
pub struct Select<'a> {
    iter: Descendants,
    selectors: &'a SelectorList,
}

impl<'a> Iterator for Select<'a> {
    type Item = NodeRef;
    fn next(&mut self) -> Option<NodeRef> {
        loop {
            let node = self.iter.next()?;
            if self.selectors.matches(&node) {
                return Some(node);
            }
        }
    }
}

pub fn select<'a>(root: &NodeRef, selectors: &'a SelectorList) -> Select<'a> {
    Select { iter: root.inclusive_descendants(), selectors }
}
