//! Command line parsing emulating the behaviour of the original tool's
//! argument parser (including its error messages).

use std::io::IsTerminal;

#[derive(Debug, Default)]
pub struct Config {
    pub attribute: Option<String>,
    pub base: Option<String>,
    pub detect_base: bool,
    pub filename: Option<String>,
    pub ignore_whitespace: bool,
    pub output: Option<String>,
    pub pretty: bool,
    pub remove_nodes: Option<Vec<String>>,
    pub text: bool,
    pub selectors: Vec<String>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    Flag,
    Opt,
}

struct ArgDef {
    name: &'static str,
    short: char,
    long: &'static str,
    kind: Kind,
    value_name: &'static str,
    multiple: bool,
}

const ARGS: &[ArgDef] = &[
    ArgDef { name: "detect-base", short: 'B', long: "detect-base", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "help", short: 'h', long: "help", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "ignore-whitespace", short: 'w', long: "ignore-whitespace", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "pretty", short: 'p', long: "pretty", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "text", short: 't', long: "text", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "version", short: 'V', long: "version", kind: Kind::Flag, value_name: "", multiple: false },
    ArgDef { name: "attribute", short: 'a', long: "attribute", kind: Kind::Opt, value_name: "attribute", multiple: false },
    ArgDef { name: "base", short: 'b', long: "base", kind: Kind::Opt, value_name: "base", multiple: false },
    ArgDef { name: "filename", short: 'f', long: "filename", kind: Kind::Opt, value_name: "FILE", multiple: false },
    ArgDef { name: "output", short: 'o', long: "output", kind: Kind::Opt, value_name: "FILE", multiple: false },
    ArgDef { name: "remove-nodes", short: 'r', long: "remove-nodes", kind: Kind::Opt, value_name: "SELECTOR", multiple: true },
];

impl ArgDef {
    fn display(&self) -> String {
        match self.kind {
            Kind::Flag => format!("--{}", self.long),
            Kind::Opt => {
                if self.multiple {
                    format!("--{} <{}>...", self.long, self.value_name)
                } else {
                    format!("--{} <{}>", self.long, self.value_name)
                }
            }
        }
    }
}

fn find_short(c: char) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.short == c)
}

fn find_long(l: &str) -> Option<&'static ArgDef> {
    ARGS.iter().find(|a| a.long == l)
}

#[derive(Default)]
struct Matched {
    occurs: usize,
    vals: Vec<String>,
}

struct Matcher {
    /// (arg name, matched) in order of first appearance.
    args: Vec<(&'static str, Matched)>,
    positionals: Vec<String>,
}

impl Matcher {
    fn get_mut(&mut self, name: &'static str) -> &mut Matched {
        if let Some(pos) = self.args.iter().position(|(n, _)| *n == name) {
            return &mut self.args[pos].1;
        }
        self.args.push((name, Matched::default()));
        &mut self.args.last_mut().unwrap().1
    }
    fn contains(&self, name: &str) -> bool {
        self.args.iter().any(|(n, _)| *n == name)
    }
    fn get(&self, name: &str) -> Option<&Matched> {
        self.args.iter().find(|(n, _)| *n == name).map(|(_, m)| m)
    }
}

pub struct Colors {
    enabled: bool,
}

impl Colors {
    fn new() -> Colors {
        let is_tty = std::io::stderr().is_terminal();
        let dumb = std::env::var("TERM").ok().as_deref() == Some("dumb");
        Colors { enabled: is_tty && !dumb }
    }
    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

pub struct Cli {
    pub bin_name: String,
}

impl Cli {
    pub fn new(argv0: Option<&str>) -> Cli {
        let bin_name = argv0
            .and_then(|a| std::path::Path::new(a).file_name().map(|f| f.to_string_lossy().into_owned()))
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| "htmlq".to_string());
        Cli { bin_name }
    }

    pub fn help_text(&self) -> String {
        format!(
            "htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    {bin} [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]",
            bin = self.bin_name
        )
    }

    fn full_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] [--] [selector]...", self.bin_name)
    }

    fn usage_with_title(&self, matcher: &Matcher) -> String {
        let mut names: Vec<&'static str> = matcher.args.iter().map(|(n, _)| *n).collect();
        names.sort();
        names.dedup();
        let body = if names.is_empty() {
            self.full_usage()
        } else {
            let mut s = self.bin_name.clone();
            for n in names {
                let def = ARGS.iter().find(|a| a.name == n).unwrap();
                s.push(' ');
                s.push_str(&def.display());
            }
            s
        };
        format!("USAGE:\n    {}", body)
    }

    fn error_unknown(&self, arg: &str, did_you_mean: &str, matcher: &Matcher) -> String {
        let c = Colors::new();
        format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            did_you_mean,
            self.usage_with_title(matcher),
            c.good("--help")
        )
    }

    fn error_empty_value(&self, def: &ArgDef, matcher: &Matcher) -> String {
        let c = Colors::new();
        format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&def.display()),
            self.usage_with_title(matcher),
            c.good("--help")
        )
    }

    fn error_multiple(&self, def: &ArgDef, matcher: &Matcher) -> String {
        let c = Colors::new();
        format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&def.display()),
            self.usage_with_title(matcher),
            c.good("--help")
        )
    }
}

pub enum Outcome {
    Run(Config),
    /// Print to stdout and exit 0.
    Stdout(String),
    /// Print to stderr and exit 1.
    Error(String),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum NeedsVal {
    None,
    Opt(&'static str),
}

pub fn parse(args: &[String]) -> Outcome {
    let cli = Cli::new(args.first().map(|s| s.as_str()));
    let mut matcher = Matcher { args: Vec::new(), positionals: Vec::new() };
    let mut needs_val = NeedsVal::None;
    let mut trailing = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if !trailing {
            let starts_new_arg = if arg.starts_with("--") {
                true
            } else if arg.starts_with('-') {
                arg.len() != 1
            } else {
                false
            };
            if starts_new_arg {
                if arg.starts_with("--") {
                    if arg.len() == 2 {
                        trailing = true;
                        continue;
                    }
                    match parse_long(&cli, &mut matcher, &arg[2..]) {
                        Ok(nv) => needs_val = nv,
                        Err(o) => return o,
                    }
                } else {
                    match parse_short(&cli, &mut matcher, &arg[1..]) {
                        Ok(nv) => needs_val = nv,
                        Err(o) => return o,
                    }
                }
                continue;
            } else if let NeedsVal::Opt(name) = needs_val {
                let def = ARGS.iter().find(|a| a.name == name).unwrap();
                needs_val = add_val(&mut matcher, def, arg.clone());
                continue;
            }
        }
        // Positional.
        matcher.positionals.push(arg.clone());
        needs_val = NeedsVal::None;
    }

    // Validation.
    if let NeedsVal::Opt(name) = needs_val {
        let def = ARGS.iter().find(|a| a.name == name).unwrap();
        let should_err = matcher.get(name).map_or(true, |m| m.vals.is_empty());
        if should_err {
            return Outcome::Error(cli.error_empty_value(def, &matcher));
        }
    }
    for (name, m) in &matcher.args {
        let def = ARGS.iter().find(|a| a.name == *name).unwrap();
        if def.kind == Kind::Opt && m.vals.is_empty() {
            return Outcome::Error(cli.error_empty_value(def, &matcher));
        }
        if m.occurs > 1 && !def.multiple {
            return Outcome::Error(cli.error_multiple(def, &matcher));
        }
    }

    let first = |name: &str| matcher.get(name).and_then(|m| m.vals.first().cloned());
    let config = Config {
        attribute: first("attribute"),
        base: first("base"),
        detect_base: matcher.contains("detect-base"),
        filename: first("filename"),
        ignore_whitespace: matcher.contains("ignore-whitespace"),
        output: first("output"),
        pretty: matcher.contains("pretty"),
        remove_nodes: matcher.get("remove-nodes").map(|m| m.vals.clone()),
        text: matcher.contains("text"),
        selectors: if matcher.positionals.is_empty() {
            vec!["html".to_string()]
        } else {
            matcher.positionals.clone()
        },
    };
    Outcome::Run(config)
}

fn add_val(matcher: &mut Matcher, def: &'static ArgDef, val: String) -> NeedsVal {
    let m = matcher.get_mut(def.name);
    m.vals.push(val);
    // number_of_values(1) for multiple options; single value otherwise.
    NeedsVal::None
}

fn check_help_version(cli: &Cli, def: &ArgDef) -> Result<(), Outcome> {
    match def.name {
        "help" => Err(Outcome::Stdout(cli.help_text())),
        "version" => Err(Outcome::Stdout("htmlq 0.4.0".to_string())),
        _ => Ok(()),
    }
}

fn parse_long(cli: &Cli, matcher: &mut Matcher, rest: &str) -> Result<NeedsVal, Outcome> {
    let (name, val) = match rest.find('=') {
        Some(idx) => (&rest[..idx], Some(&rest[idx..])),
        None => (rest, None),
    };
    if let Some(def) = find_long(name) {
        match def.kind {
            Kind::Opt => return Ok(parse_opt(cli, matcher, def, val, true)?),
            Kind::Flag => {
                check_help_version(cli, def)?;
                let m = matcher.get_mut(def.name);
                m.occurs += 1;
                return Ok(NeedsVal::None);
            }
        }
    }
    // Unknown long argument: suggestions.
    let longs: Vec<&str> = ARGS.iter().map(|a| a.long).collect();
    let suggestion = did_you_mean(name, &longs);
    let suffix = match suggestion {
        Some(cand) => {
            // Add the suggested arg to the matcher for the usage string.
            let def = find_long(cand).unwrap();
            matcher.get_mut(def.name);
            format!("\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?", cand)
        }
        None => String::new(),
    };
    let used = format!("--{}", name);
    Err(Outcome::Error(cli.error_unknown(&used, &suffix, matcher)))
}

fn parse_short(cli: &Cli, matcher: &mut Matcher, full: &str) -> Result<NeedsVal, Outcome> {
    let arg = full.trim_start_matches('-');
    let mut ret = NeedsVal::None;
    for c in arg.chars() {
        if let Some(def) = find_short(c) {
            match def.kind {
                Kind::Opt => {
                    let mut parts = arg.splitn(2, c);
                    let p0 = parts.next().unwrap_or("");
                    let p1 = parts.next().unwrap_or("");
                    let idx = p0.len() + c.len_utf8();
                    let val = if !p1.is_empty() { Some(&arg[idx..]) } else { None };
                    return parse_opt(cli, matcher, def, val, false);
                }
                Kind::Flag => {
                    check_help_version(cli, def)?;
                    let m = matcher.get_mut(def.name);
                    m.occurs += 1;
                    ret = NeedsVal::None;
                }
            }
        } else {
            let used = format!("-{}", c);
            return Err(Outcome::Error(cli.error_unknown(&used, "", matcher)));
        }
    }
    Ok(ret)
}

fn parse_opt(
    _cli: &Cli,
    matcher: &mut Matcher,
    def: &'static ArgDef,
    val: Option<&str>,
    _had_eq: bool,
) -> Result<NeedsVal, Outcome> {
    let no_val = val.is_none();
    if let Some(fv) = val {
        let v = fv.trim_start_matches('=');
        let m = matcher.get_mut(def.name);
        m.vals.push(v.to_string());
    }
    let m = matcher.get_mut(def.name);
    m.occurs += 1;
    if no_val {
        return Ok(NeedsVal::Opt(def.name));
    }
    Ok(NeedsVal::None)
}

// ---- "did you mean" using Jaro-Winkler similarity ----

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let jw = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean<'a>(v: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(f64, &'a str)> = None;
    for pv in candidates {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && best.map_or(true, |(c, _)| c < confidence) {
            best = Some((confidence, pv));
        }
    }
    best.map(|(_, c)| c)
}
