fn panic_exit(line: u32, col: u32, msg: &str) -> ! {
    let pid = std::process::id();
    let mut err = std::io::stderr();
    let _ = write!(err, "\nthread 'main' ({}) panicked at src/main.rs:{}:{}:\n{}\n", pid, line, col, msg);
    match std::env::var("RUST_BACKTRACE") {
        Ok(v) if v != "0" && !v.is_empty() => {
            let _ = write!(
                err,
                "stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n"
            );
        }
        _ => {
            let _ = write!(err, "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
        }
    }
    let _ = err.flush();
    std::process::exit(101);
}

fn io_error_debug(e: &std::io::Error) -> String {
    format!("{:?}", e)
}

fn parse_html(input: &str) -> NodeRef {
    let mut tb = treebuilder::TreeBuilder::new();
    {
        let mut tok = tokenizer::Tokenizer::new(input, &mut tb);
        tok.run();
    }
    tb.document
}

fn select_first_base_href(document: &NodeRef) -> Option<String> {
    let sel = SelectorList::parse("base").ok()?;
    let node = selectors::select(document, &sel).next()?;
    let e = node.as_element()?;
    let attrs = e.attributes.borrow();
    attrs.get("href").map(|s| s.to_string())
}

fn is_special_scheme(s: &str) -> bool {
    matches!(s, "http" | "https" | "ws" | "wss" | "ftp" | "file")
}

/// Compensate for differences between URL library versions.
fn fix_url_serialization(u: &url::Url) -> String {
    let mut s = u.to_string();
    let scheme = u.scheme();
    if scheme == "file" {
        // Normalise a Windows drive letter written with '|' as the first path segment.
        let prefix = "file:///";
        if s.starts_with(prefix) {
            let rest = &s[prefix.len()..];
            let b = rest.as_bytes();
            if b.len() >= 2
                && b[0].is_ascii_alphabetic()
                && b[1] == b'|'
                && (b.len() == 2 || matches!(b[2], b'/' | b'\\' | b'?' | b'#'))
            {
                let mut out = String::with_capacity(s.len());
                out.push_str(prefix);
                out.push(b[0] as char);
                out.push(':');
                out.push_str(&rest[2..]);
                s = out;
            }
        }
    } else if !is_special_scheme(scheme) {
        let marker = format!("{}:/.//", scheme);
        if s.starts_with(&marker) {
            s = format!("{}://{}", scheme, &s[marker.len()..]);
        }
    }
    s
}

fn rewrite_href(base: &url::Url, href: &str) -> String {
    if href.starts_with("////") {
        return href.trim_start_matches('/').to_string();
    }
    match base.join(href) {
        Ok(u) => fix_url_serialization(&u),
        Err(_) => base.to_string(),
    }
}

